def _load_frontend_template() -> str:
    base_dir = getattr(sys, "_MEIPASS", os.path.dirname(os.path.abspath(__file__)))
    ui_dir = os.path.join(base_dir, "ui")
    with open(os.path.join(ui_dir, "index.html"), "r", encoding="utf-8") as f:
        html_tpl = f.read()
    with open(os.path.join(ui_dir, "styles.css"), "r", encoding="utf-8") as f:
        css_text = f.read()
    with open(os.path.join(ui_dir, "app.js"), "r", encoding="utf-8") as f:
        js_text = f.read()
    return (
        html_tpl
        .replace("/* __INLINE_STYLES__ */", css_text, 1)
        .replace("/* __INLINE_SCRIPTS__ */", js_text, 1)
        .replace("__ALIPAY_QR_BASE64__", ALIPAY_QR_BASE64)
        .replace("__DISCFLOW_ICON_SVG_512__", DISCFLOW_ICON_SVG_512)
        .replace("__DISCFLOW_ICON_SVG_24__", DISCFLOW_ICON_SVG_24)
        .replace("__APP_VERSION__", APP_VERSION)
        .replace("__APP_NAME__", APP_NAME)
    )


_FRONTEND_HTML_TEMPLATE = _load_frontend_template()


def render_frontend_html(init_prefs: Optional[dict] = None, init_state: Optional[dict] = None) -> str:
    """将用户主题偏好与初始状态同步注入首帧 HTML，消除启动主题与内容闪烁"""
    theme = "light" if isinstance(init_prefs, dict) and init_prefs.get("themeMode") == "light" else "dark"
    clean_prefs = dict(init_prefs) if isinstance(init_prefs, dict) else {}
    clean_prefs.pop("closeToTray", None)
    prefs_json = json.dumps(clean_prefs, ensure_ascii=False).replace("</", "<\\/")
    state_json = (
        json.dumps(init_state, ensure_ascii=False).replace("</", "<\\/")
        if init_state is not None
        else "null"
    )
    return (
        _FRONTEND_HTML_TEMPLATE
        .replace("__INIT_THEME__", theme)
        .replace("__INITIAL_PREFS_JSON__", prefs_json)
        .replace("__INITIAL_STATE_JSON__", state_json)
    )


APPLE_MUSIC_HTML = render_frontend_html()


class GlobalMediaKeyListener:
    """Windows 后台全局多媒体按键监听器 (WH_KEYBOARD_LL + 线程消息循环)"""

    def __init__(
        self,
        on_play_pause: Callable[[], None],
        on_next: Callable[[], None],
        on_prev: Callable[[], None],
        on_stop: Callable[[], None],
    ):
        self.on_play_pause = on_play_pause
        self.on_next = on_next
        self.on_prev = on_prev
        self.on_stop = on_stop
        self._thread: Optional[threading.Thread] = None
        self._thread_id: int = 0
        self._hook = None
        self._c_proc = None

    def start(self):
        self._thread = threading.Thread(target=self._run, daemon=True)
        self._thread.start()

    def stop(self):
        if self._thread_id:
            try:
                ctypes.windll.user32.PostThreadMessageW(self._thread_id, 0x0012, 0, 0)  # WM_QUIT
            except Exception:
                pass
        if self._thread and self._thread.is_alive():
            try:
                self._thread.join(timeout=0.6)
            except Exception:
                pass
        self._thread = None

    def _run(self):
        user32 = ctypes.WinDLL("user32", use_last_error=True)
        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        self._thread_id = kernel32.GetCurrentThreadId()

        class KBDLLHOOKSTRUCT(ctypes.Structure):
            _fields_ = [
                ("vkCode", wintypes.DWORD),
                ("scanCode", wintypes.DWORD),
                ("flags", wintypes.DWORD),
                ("time", wintypes.DWORD),
                ("dwExtraInfo", ctypes.c_size_t),
            ]

        HOOKPROC = ctypes.WINFUNCTYPE(
            ctypes.c_longlong,
            ctypes.c_int,
            wintypes.WPARAM,
            wintypes.LPARAM,
        )

        user32.SetWindowsHookExW.argtypes = [ctypes.c_int, HOOKPROC, wintypes.HINSTANCE, wintypes.DWORD]
        user32.SetWindowsHookExW.restype = wintypes.HHOOK
        user32.CallNextHookEx.argtypes = [wintypes.HHOOK, ctypes.c_int, wintypes.WPARAM, wintypes.LPARAM]
        user32.CallNextHookEx.restype = ctypes.c_longlong
        user32.UnhookWindowsHookEx.argtypes = [wintypes.HHOOK]
        user32.UnhookWindowsHookEx.restype = wintypes.BOOL

        def hook_proc(nCode, wParam, lParam):
            if nCode == 0 and wParam in (0x0100, 0x0104):  # WM_KEYDOWN, WM_SYSKEYDOWN
                try:
                    kbd = ctypes.cast(lParam, ctypes.POINTER(KBDLLHOOKSTRUCT)).contents
                    vk = kbd.vkCode
                    if vk == 0xB3:  # VK_MEDIA_PLAY_PAUSE
                        threading.Thread(target=self.on_play_pause, daemon=True).start()
                    elif vk == 0xB0:  # VK_MEDIA_NEXT_TRACK
                        threading.Thread(target=self.on_next, daemon=True).start()
                    elif vk == 0xB1:  # VK_MEDIA_PREV_TRACK
                        threading.Thread(target=self.on_prev, daemon=True).start()
                    elif vk == 0xB2:  # VK_MEDIA_STOP
                        threading.Thread(target=self.on_stop, daemon=True).start()
                except Exception:
                    pass
            return user32.CallNextHookEx(self._hook, nCode, wParam, lParam)

        self._c_proc = HOOKPROC(hook_proc)
        self._hook = user32.SetWindowsHookExW(13, self._c_proc, None, 0)  # WH_KEYBOARD_LL = 13
        try:
            msg = wintypes.MSG()
            while user32.GetMessageW(ctypes.byref(msg), None, 0, 0) > 0:
                user32.TranslateMessage(ctypes.byref(msg))
                user32.DispatchMessageW(ctypes.byref(msg))
        finally:
            if self._hook:
                try:
                    user32.UnhookWindowsHookEx(self._hook)
                except Exception:
                    pass
                self._hook = None


