class DiscflowController:
    def __init__(self):
        self._window: Optional[webview.Window] = None
        self._lock = threading.Lock()
        self._closed = False
        self._booted = False
        self._boot_scanning = False

        # 状态版本号：前端轮询仅在版本号变更时才拉取大型 Base64 封面或歌单/歌词，彻底消除跨线程 evaluate_js 死锁
        self._meta_version: int = 1
        self._lyrics_version: int = 1
        self._load_token: int = 0
        self._watcher_miss_count: Dict[str, int] = {}
        self._non_audio_drives: set = set()

        self._cached_drives: List[str] = []
        self.current_toc: Optional[CdDiscToc] = None
        self.current_drive: str = ""
        self.current_track_index: int = 0
        self.elapsed_sec: float = 0.0
        self.duration_sec: float = 0.0
        self.is_loading: bool = True
        self.status_text: str = f"正在扫描 {APP_NAME} 光驱设备..."

        self.album_title: str = "等待放入音频 CD"
        self.artist: str = "未检测到音频光盘 · 放入 CD 后将自动识别"
        self.year: str = ""
        self.source: str = ""
        self.cover_data_url: str = ""

        self.play_mode: str = "order"  # "order" | "shuffle" | "one"

        self.library_manager = DiscflowLibraryManager()
        self.ripper_task: Optional[CdRipperTask] = None

        self.lyrics_cache: Dict[int, List[dict]] = {}
        # 被用户手动指定并锁定的曲目编号：自动预取不得覆盖
        self.lyrics_locked_tracks: set = set()
        # 批量匹配未命中的曲目编号：前端在曲目行标出「待匹配」，引导逐轨手动指定
        self.lyrics_missed_tracks: set = set()
        # 整专辑歌词批量套用进度（供前端展示）
        self._lyrics_batch = {"running": False, "done": 0, "total": 0, "matched": 0, "missed": []}
        # 每轨对应的歌曲 ID（来源 + id），用于歌词直取
        self.track_song_ids: Dict[int, dict] = {}
        self.current_lyrics: List[dict] = []

        # 歌词时间轴微调记忆 (秒)
        self.track_lyrics_offsets: Dict[str, float] = {}
        try:
            saved_offsets = load_user_preferences().get("lyricOffsets", {})
            if isinstance(saved_offsets, dict):
                self.track_lyrics_offsets = {str(k): float(v) for k, v in saved_offsets.items()}
        except Exception:
            pass

        self.player = CddaWaveOutPlayer(
            on_position=self._on_player_position,
            on_finished=self._on_player_finished,
            on_error=self._on_player_error,
            on_track_transition=self._on_player_track_transition,
        )

        # 启动后台全局媒体按键监听器 (后台/最小化时响应播放/暂停/上一曲/下一曲)
        self._media_keys = GlobalMediaKeyListener(
            on_play_pause=self.toggle_play_pause,
            on_next=self.next_track,
            on_prev=self.prev_track,
            on_stop=self.stop,
        )
        self._media_keys.start()

        # 启动时恢复上次保存的音量（preferences.json），并立即作用到播放引擎
        try:
            init_prefs = load_user_preferences()
            self.volume_pct: int = int(max(0, min(100, int(init_prefs.get("volume", 80)))))
            self._ignored_update_version: str = str(init_prefs.get("ignoredUpdateVersion", "") or "")
        except Exception:
            self.volume_pct = 80
            self._ignored_update_version = ""
        self.player.set_volume(self.volume_pct / 100.0)

        self._hwnd: int = 0
        self._is_maximized: bool = False
        self._last_normal_bounds: dict = {}
        self._bounds_save_timer: Optional[threading.Timer] = None
        self._bounds_lock = threading.Lock()

        self._update_info: Optional[dict] = None
        self._update_download_lock = threading.Lock()
        self._update_cancel_event = threading.Event()
        self._update_download_state: dict = {
            "status": "idle",
            "progressPct": 0.0,
            "downloadedBytes": 0,
            "totalBytes": 0,
            "statusText": "",
            "error": "",
            "filePath": "",
        }
        self._lyrics_fetching_keys: set = set()
        self._saved_maximized: bool = False
        self._push_event = threading.Event()
        self._last_pushed_meta_ver: int = -1
        self._last_pushed_lyrics_ver: int = -1
        self._last_pushed_track_idx: int = -1

        # 无盘启动时于首帧创建前静默预恢复上次会话，避免主屏空窗闪烁
        self._initial_session_resumed: bool = False
        if not is_under_test_runner():
            try:
                phys = WindowsCdDriveManager.list_physical_cdrom_drives()
                self._cached_drives = phys
                if not any(WindowsCdDriveManager.is_disc_ready(d) for d in phys):
                    self._initial_session_resumed = self._try_resume_last_session()
            except Exception:
                pass

    @staticmethod
    def _normalize_bounds_dict(wb: dict, scale: float, log_vx: float, log_vy: float, log_vw: float, log_vh: float) -> tuple:
        """将存储的 windowBounds（兼容旧版物理像素无 logical 标记格式）统一转换为合法的逻辑像素边界"""
        is_logical = bool(wb.get("logical", False))
        sw = float(wb.get("width", 1120) or 1120)
        sh = float(wb.get("height", 740) or 740)
        if not is_logical and scale > 1.01:
            sw /= scale
            sh /= scale
        max_w = max(880, int(round(log_vw)))
        max_h = max(620, int(round(log_vh)))
        w = max(880, min(max_w, int(round(sw))))
        h = max(620, min(max_h, int(round(sh))))
        maximized = bool(wb.get("maximized", False))
        x, y = None, None
        if wb.get("x") is not None and wb.get("y") is not None:
            sx = float(wb.get("x"))
            sy = float(wb.get("y"))
            if not is_logical and scale > 1.01:
                sx /= scale
                sy /= scale
            if (log_vx - w + 120) <= sx <= (log_vx + log_vw - 120) and (log_vy - 40) <= sy <= (log_vy + log_vh - 80):
                min_x = int(round(log_vx))
                min_y = int(round(log_vy))
                max_x = max(min_x, int(round(log_vx + log_vw - w)))
                max_y = max(min_y, int(round(log_vy + log_vh - h)))
                x = max(min_x, min(max_x, int(round(sx))))
                y = max(min_y, min(max_y, int(round(sy))))
        return w, h, x, y, maximized

    @staticmethod
    def _load_initial_window_bounds() -> tuple:
        """读取上次关闭前保存的窗口尺寸、坐标与最大化状态（96-DPI 逻辑像素），并钳制在桌面可见范围内"""
        _enable_dpi_awareness()
        w, h, x, y, maximized = 1120, 740, None, None, False
        try:
            prefs = load_user_preferences()
            wb = prefs.get("windowBounds")
            if isinstance(wb, dict) and wb:
                scale = _get_dpi_scale(0)
                user32 = ctypes.windll.user32
                vx = float(user32.GetSystemMetrics(76))
                vy = float(user32.GetSystemMetrics(77))
                vw = float(user32.GetSystemMetrics(78) or 1920)
                vh = float(user32.GetSystemMetrics(79) or 1080)
                log_vx = vx / scale
                log_vy = vy / scale
                log_vw = (vw / scale) or 1920.0
                log_vh = (vh / scale) or 1080.0
                w, h, x, y, maximized = DiscflowController._normalize_bounds_dict(
                    wb, scale, log_vx, log_vy, log_vw, log_vh
                )
        except Exception:
            pass
        return w, h, x, y, maximized

    @staticmethod
    def _rect_to_logical_bounds(left: int, top: int, right: int, bottom: int, scale: float, is_zoomed: bool, prev_wb: dict) -> dict:
        """把 Win32 GetWindowRect 的物理坐标转为 96-DPI 逻辑坐标字典"""
        safe_scale = scale if scale > 0.2 else 1.0
        if not is_zoomed:
            return {
                "x": int(round(left / safe_scale)),
                "y": int(round(top / safe_scale)),
                "width": max(880, int(round((right - left) / safe_scale))),
                "height": max(620, int(round((bottom - top) / safe_scale))),
                "maximized": False,
                "logical": True,
            }
        prev_logical = bool(prev_wb.get("logical", False))
        pw = float(prev_wb.get("width", 1120) or 1120)
        ph = float(prev_wb.get("height", 740) or 740)
        px = prev_wb.get("x")
        py = prev_wb.get("y")
        if not prev_logical and safe_scale > 1.01:
            pw /= safe_scale
            ph /= safe_scale
            if px is not None:
                px = int(round(float(px) / safe_scale))
            if py is not None:
                py = int(round(float(py) / safe_scale))
        return {
            "x": int(px) if px is not None else None,
            "y": int(py) if py is not None else None,
            "width": max(880, int(round(pw))),
            "height": max(620, int(round(ph))),
            "maximized": True,
            "logical": True,
        }

    def _schedule_bounds_save(self):
        with self._bounds_lock:
            if self._bounds_save_timer is not None:
                try:
                    self._bounds_save_timer.cancel()
                except Exception:
                    pass
            timer = threading.Timer(0.35, self._save_window_bounds)
            timer.daemon = True
            self._bounds_save_timer = timer
            timer.start()

    def _on_window_moved(self, x, y):
        try:
            if self._is_maximized:
                return
            hwnd = self._hwnd
            if hwnd:
                user32 = ctypes.windll.user32
                if user32.IsZoomed(hwnd) or user32.IsIconic(hwnd):
                    return
            self._last_normal_bounds["x"] = int(x)
            self._last_normal_bounds["y"] = int(y)
            self._schedule_bounds_save()
        except Exception:
            pass

    def _on_window_resized(self, width, height):
        try:
            if self._is_maximized:
                return
            hwnd = self._hwnd
            if hwnd:
                user32 = ctypes.windll.user32
                if user32.IsZoomed(hwnd) or user32.IsIconic(hwnd):
                    return
            self._last_normal_bounds["width"] = max(880, int(width))
            self._last_normal_bounds["height"] = max(620, int(height))
            self._schedule_bounds_save()
        except Exception:
            pass

    def _on_window_maximized(self):
        self._is_maximized = True
        self._schedule_bounds_save()

    def _on_window_restored(self):
        self._is_maximized = False
        self._schedule_bounds_save()

    def _save_window_bounds(self):
        """将当前窗口尺寸/坐标（96-DPI 逻辑像素）与最大化状态持久化到 preferences.json"""
        with self._bounds_lock:
            if self._bounds_save_timer is not None:
                try:
                    self._bounds_save_timer.cancel()
                except Exception:
                    pass
                self._bounds_save_timer = None
            try:
                prev_prefs = load_user_preferences()
                prev_wb = prev_prefs.get("windowBounds") if isinstance(prev_prefs.get("windowBounds"), dict) else {}
                hwnd = self._hwnd
                if not hwnd and self._window is not None:
                    native = getattr(self._window, "native", None)
                    if native is not None and not getattr(native, "InvokeRequired", False):
                        try:
                            hwnd = int(native.Handle.ToInt64()) if hasattr(native, "Handle") else 0
                            if hwnd:
                                self._hwnd = hwnd
                        except Exception:
                            hwnd = 0

                if hwnd:
                    user32 = ctypes.windll.user32
                    if user32.IsWindow(hwnd):
                        if user32.IsIconic(hwnd):
                            return
                        is_zoomed = bool(user32.IsZoomed(hwnd))
                        rect = wintypes.RECT()
                        if user32.GetWindowRect(hwnd, ctypes.byref(rect)):
                            scale = _get_dpi_scale(hwnd)
                            base_prev = self._last_normal_bounds or prev_wb
                            wb = self._rect_to_logical_bounds(
                                rect.left, rect.top, rect.right, rect.bottom,
                                scale, is_zoomed, base_prev,
                            )
                            if not is_zoomed:
                                self._last_normal_bounds = {
                                    "x": wb["x"],
                                    "y": wb["y"],
                                    "width": wb["width"],
                                    "height": wb["height"],
                                }
                            save_user_preferences({"windowBounds": wb})
                            return

                if self._last_normal_bounds:
                    wb = {
                        "x": self._last_normal_bounds.get("x", prev_wb.get("x")),
                        "y": self._last_normal_bounds.get("y", prev_wb.get("y")),
                        "width": max(880, int(self._last_normal_bounds.get("width", prev_wb.get("width", 1120)) or 1120)),
                        "height": max(620, int(self._last_normal_bounds.get("height", prev_wb.get("height", 740)) or 740)),
                        "maximized": bool(self._is_maximized),
                        "logical": True,
                    }
                    save_user_preferences({"windowBounds": wb})
            except Exception:
                pass

    def bind_window(self, win: webview.Window):
        self._window = win
        self._is_maximized = bool(getattr(self, "_saved_maximized", False))
        try:
            w, h, x, y, _ = self._load_initial_window_bounds()
            self._last_normal_bounds = {"width": w, "height": h}
            if x is not None and y is not None:
                self._last_normal_bounds["x"] = x
                self._last_normal_bounds["y"] = y
        except Exception:
            pass
        try:
            if hasattr(win, "events"):
                win.events.moved += self._on_window_moved
                win.events.resized += self._on_window_resized
                win.events.maximized += self._on_window_maximized
                win.events.restored += self._on_window_restored
        except Exception:
            pass

    def _apply_win11_rounded_corners(self):
        """在 WinForms UI 线程缓存窗口句柄，并启用 Windows 11 原生 DWM 圆角与匹配当前主题的属性"""
        try:
            if not self._window:
                return
            native = getattr(self._window, "native", None)
            if native is None:
                return

            def _apply():
                try:
                    hwnd = int(native.Handle.ToInt64()) if hasattr(native, "Handle") else 0
                    if hwnd:
                        self._hwnd = hwnd
                        dwmapi = ctypes.windll.dwmapi
                        pref = ctypes.c_int(2)  # DWMWCP_ROUND
                        dwmapi.DwmSetWindowAttribute(hwnd, 33, ctypes.byref(pref), ctypes.sizeof(pref))
                        theme = str(load_user_preferences().get("themeMode", "dark") or "dark")
                        dark_pref = ctypes.c_int(1 if theme == "dark" else 0)
                        dwmapi.DwmSetWindowAttribute(hwnd, 20, ctypes.byref(dark_pref), ctypes.sizeof(dark_pref))
                except Exception:
                    pass

            if getattr(native, "InvokeRequired", False):
                import System
                native.BeginInvoke(System.Action(_apply))
            else:
                _apply()
        except Exception:
            pass

    def set_theme_mode(self, mode: str) -> bool:
        """同步持久化外观主题并即时刷新原生窗体 DWM 属性及背景色"""
        norm = "light" if str(mode or "").strip().lower() == "light" else "dark"
        ok = save_user_preferences({"themeMode": norm})
        try:
            if self._window:
                native = getattr(self._window, "native", None)
                if native is not None:
                    import System
                    import System.Drawing as SD

                    def _sync_native():
                        try:
                            hwnd = self._hwnd or (int(native.Handle.ToInt64()) if hasattr(native, "Handle") else 0)
                            if hwnd:
                                self._hwnd = hwnd
                                dark_pref = ctypes.c_int(1 if norm == "dark" else 0)
                                ctypes.windll.dwmapi.DwmSetWindowAttribute(
                                    hwnd, 20, ctypes.byref(dark_pref), ctypes.sizeof(dark_pref)
                                )
                            bg = SD.ColorTranslator.FromHtml("#F5F5F7" if norm == "light" else "#000000")
                            native.BackColor = bg
                            if hasattr(native, "browser") and getattr(native.browser, "webview", None):
                                native.browser.webview.DefaultBackgroundColor = bg
                        except Exception:
                            pass

                    if getattr(native, "InvokeRequired", False):
                        native.BeginInvoke(System.Action(_sync_native))
                    else:
                        _sync_native()
        except Exception:
            pass
        return ok

    def begin_window_resize(self, edge_code: int):
        """无边框窗口 8 向边缘拖拽缩放（委托给 Win32 WM_SYSCOMMAND SC_SIZE）"""
        if edge_code not in range(1, 9) or not self._window:
            return
        try:
            native = getattr(self._window, "native", None)
            if native is None:
                return
            import System

            def _do_resize():
                try:
                    hwnd = int(native.Handle.ToInt64())
                    if hwnd:
                        self._hwnd = hwnd
                    if hwnd and not ctypes.windll.user32.IsZoomed(hwnd):
                        ctypes.windll.user32.ReleaseCapture()
                        ctypes.windll.user32.SendMessageW(hwnd, 0x0112, 0xF000 + int(edge_code), 0)
                except Exception:
                    pass

            native.BeginInvoke(System.Action(_do_resize))
        except Exception:
            pass

    def minimize_window(self):
        if self._window:
            try:
                self._window.minimize()
            except Exception:
                pass

    def toggle_maximize_window(self) -> bool:
        if not self._window:
            return False
        try:
            if getattr(self, "_is_maximized", False):
                self._window.restore()
                self._is_maximized = False
            else:
                self._window.maximize()
                self._is_maximized = True
            self._schedule_bounds_save()
        except Exception:
            pass
        return bool(getattr(self, "_is_maximized", False))

    def close_window(self):
        self.exit_app()

    def on_window_closing(self):
        self._save_window_bounds()
        return True

    def exit_app(self):
        self._save_window_bounds()
        if self._window:
            try:
                self._window.destroy()
            except Exception:
                pass

    def shutdown(self):
        self._closed = True
        self._update_cancel_event.set()
        self._save_window_bounds()
        self._save_session_state()
        if hasattr(self, "_media_keys") and self._media_keys:
            self._media_keys.stop()
        self.player.close()

    @staticmethod
    def _parse_version_tuple(ver_str: str) -> tuple:
        nums = [int(x) for x in re.findall(r"\d+", str(ver_str or ""))]
        while len(nums) < 3:
            nums.append(0)
        return tuple(nums[:4])

    def check_for_updates(self, force: bool = False) -> dict:
        if not force and self._update_info is not None:
            return dict(self._update_info)
        res = {
            "ok": False,
            "currentVersion": APP_VERSION,
            "latestVersion": APP_VERSION,
            "hasUpdate": False,
            "ignored": False,
            "releaseUrl": GITHUB_RELEASES_PAGE,
            "downloadUrl": "",
            "assetSize": 0,
            "notes": "",
            "publishedAt": "",
            "error": "",
        }
        try:
            r = requests.get(
                GITHUB_RELEASES_API,
                headers={"Accept": "application/vnd.github+json", "User-Agent": f"{APP_NAME}/{APP_VERSION}"},
                timeout=6,
            )
            if r.status_code == 200:
                data = r.json()
                raw_tag = str(data.get("tag_name") or "").strip()
                tag = raw_tag.lstrip("vV").strip()
                has_upd = bool(tag and self._parse_version_tuple(tag) > self._parse_version_tuple(APP_VERSION))

                download_url = ""
                asset_size = 0
                fallback_url = ""
                fallback_size = 0
                for ast in (data.get("assets") or []):
                    if not isinstance(ast, dict):
                        continue
                    aname = str(ast.get("name") or "").lower()
                    aurl = str(ast.get("browser_download_url") or "")
                    if aname.endswith(".exe") and aurl:
                        if "discflow" in aname:
                            download_url = aurl
                            asset_size = int(ast.get("size") or 0)
                            break
                        if not fallback_url:
                            fallback_url = aurl
                            fallback_size = int(ast.get("size") or 0)
                if not download_url:
                    download_url = fallback_url
                    asset_size = fallback_size
                if not download_url and has_upd and raw_tag:
                    download_url = f"https://github.com/JiAng10es/Discflow/releases/download/{raw_tag}/Discflow.exe"

                res.update({
                    "ok": True,
                    "latestVersion": tag or APP_VERSION,
                    "hasUpdate": has_upd,
                    "ignored": bool(has_upd and tag == self._ignored_update_version),
                    "releaseUrl": str(data.get("html_url") or GITHUB_RELEASES_PAGE),
                    "downloadUrl": download_url,
                    "assetSize": asset_size,
                    "notes": str(data.get("body") or ""),
                    "publishedAt": str(data.get("published_at") or ""),
                })
                self._update_info = res
                log_runtime_event("UPDATE", f"API 检查成功 latest={tag or APP_VERSION} hasUpdate={has_upd}")
                if has_upd:
                    self._bump_meta()
                return dict(res)

            log_runtime_event("UPDATE", f"GitHub API 返回 HTTP {r.status_code}，尝试网页重定向兜底", level="WARNING")
            # GitHub REST API 遭遇 403/429 限流时，自动回退网页端 releases/latest 重定向探测（无 API 配额限制）
            web_r = requests.get(
                f"{GITHUB_RELEASES_PAGE}/latest",
                headers={"User-Agent": f"{APP_NAME}/{APP_VERSION}"},
                allow_redirects=True,
                timeout=6,
            )
            final_url = str(getattr(web_r, "url", "") or "")
            if web_r.status_code == 200 and "/releases/tag/" in final_url:
                raw_tag = final_url.rstrip("/").rsplit("/", 1)[-1].strip()
                tag = raw_tag.lstrip("vV").strip()
                has_upd = bool(tag and self._parse_version_tuple(tag) > self._parse_version_tuple(APP_VERSION))
                log_runtime_event("UPDATE", f"网页兜底检查成功 latest={tag or APP_VERSION} hasUpdate={has_upd}")
                download_url = f"https://github.com/JiAng10es/Discflow/releases/download/{raw_tag}/Discflow.exe"
                asset_size = 0
                if has_upd:
                    try:
                        hr = requests.head(
                            download_url,
                            headers={"User-Agent": f"{APP_NAME}/{APP_VERSION}"},
                            allow_redirects=True,
                            timeout=4,
                        )
                        if hr.status_code == 200:
                            asset_size = int(hr.headers.get("Content-Length") or 0)
                    except Exception:
                        pass
                res.update({
                    "ok": True,
                    "latestVersion": tag or APP_VERSION,
                    "hasUpdate": has_upd,
                    "ignored": bool(has_upd and tag == self._ignored_update_version),
                    "releaseUrl": final_url,
                    "downloadUrl": download_url if has_upd else "",
                    "assetSize": asset_size,
                })
                self._update_info = res
                if has_upd:
                    self._bump_meta()
                return dict(res)

            res["error"] = f"HTTP {r.status_code}"
            return res
        except Exception as e:
            res["error"] = str(e)
        return dict(res)

    def ignore_update_version(self, ver: str) -> bool:
        clean = str(ver or "").lstrip("vV").strip()
        self._ignored_update_version = clean
        if self._update_info and self._update_info.get("latestVersion") == clean:
            self._update_info["ignored"] = True
        return save_user_preferences({"ignoredUpdateVersion": clean})

    def _auto_check_updates_bg(self):
        time.sleep(2.5)
        if not self._closed:
            self.check_for_updates(force=True)

    @staticmethod
    def _resolve_update_target_exe() -> str:
        """定位当前运行实例对应的目标 Discflow.exe 路径"""
        if getattr(sys, "frozen", False):
            return os.path.abspath(sys.executable)
        return os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "Discflow.exe"))

    @staticmethod
    def _build_self_update_script(pid: int, staged_exe: str, target_exe: str) -> str:
        """生成静默自更新批处理脚本：等待旧进程退出 -> 覆盖目标 EXE -> 重启新版 -> 自删"""
        src = staged_exe.replace('"', "")
        dst = target_exe.replace('"', "")
        return (
            "@echo off\r\n"
            "chcp 65001 >nul\r\n"
            f'set "PID={int(pid)}"\r\n'
            f'set "SRC={src}"\r\n'
            f'set "DST={dst}"\r\n'
            "set /a wait_cnt=0\r\n"
            ":waitloop\r\n"
            'tasklist /FI "PID eq %PID%" 2>NUL | find /I "%PID%" >NUL\r\n'
            "if not errorlevel 1 (\r\n"
            "    set /a wait_cnt+=1\r\n"
            "    if %wait_cnt% GEQ 25 goto moveloop\r\n"
            "    timeout /t 1 /nobreak >NUL\r\n"
            "    goto waitloop\r\n"
            ")\r\n"
            "set /a tries=0\r\n"
            ":moveloop\r\n"
            'move /Y "%SRC%" "%DST%" >NUL 2>NUL\r\n'
            "if not errorlevel 1 goto launch\r\n"
            "set /a tries+=1\r\n"
            "if %tries% GEQ 15 goto finish\r\n"
            "timeout /t 1 /nobreak >NUL\r\n"
            "goto moveloop\r\n"
            ":launch\r\n"
            'start "" "%DST%"\r\n'
            ":finish\r\n"
            'del "%~f0" >NUL 2>&1\r\n'
        )

    def _set_update_download_state(self, **kwargs):
        with self._update_download_lock:
            self._update_download_state.update(kwargs)

    def get_update_download_progress(self) -> dict:
        with self._update_download_lock:
            return dict(self._update_download_state)

    def cancel_update_download(self) -> dict:
        self._update_cancel_event.set()
        self._set_update_download_state(status="cancelled", statusText="已取消下载")
        return {"ok": True}

    def start_update_download(self) -> dict:
        if self._update_info is None or not self._update_info.get("downloadUrl"):
            self.check_for_updates(force=True)
        info = self._update_info or {}
        if not info.get("hasUpdate"):
            return {"ok": False, "reason": "当前已是最新版本"}
        download_url = str(info.get("downloadUrl") or "").strip()
        if not download_url:
            return {"ok": False, "reason": "未找到可下载的 Windows 更新包"}

        with self._update_download_lock:
            if self._update_download_state.get("status") in ("downloading", "installing"):
                return {"ok": True, "alreadyRunning": True}
            self._update_cancel_event.clear()
            expected_size = int(info.get("assetSize") or 0)
            latest_ver = str(info.get("latestVersion") or "")
            self._update_download_state = {
                "status": "downloading",
                "progressPct": 0.0,
                "downloadedBytes": 0,
                "totalBytes": expected_size,
                "statusText": f"正在连接并下载 v{latest_ver}...",
                "error": "",
                "filePath": "",
            }

        threading.Thread(
            target=self._download_and_install_update_worker,
            args=(download_url, latest_ver, expected_size),
            daemon=True,
        ).start()
        return {"ok": True}

    def _download_and_install_update_worker(self, download_url: str, expected_version: str, expected_size: int = 0):
        target_exe = self._resolve_update_target_exe()
        target_dir = os.path.dirname(target_exe) or tempfile.gettempdir()
        try:
            os.makedirs(target_dir, exist_ok=True)
        except Exception:
            target_dir = tempfile.gettempdir()
        tmp_path = os.path.join(target_dir, "Discflow.exe.new.tmp")
        staged_path = os.path.join(target_dir, "Discflow.exe.update.exe")

        try:
            log_runtime_event("UPDATE", f"开始下载更新 v{expected_version} url={download_url}")
            with requests.get(
                download_url,
                stream=True,
                timeout=(8, 30),
                headers={"User-Agent": f"{APP_NAME}/{APP_VERSION}"},
            ) as resp:
                resp.raise_for_status()
                total_bytes = int(resp.headers.get("Content-Length") or expected_size or 0)
                downloaded = 0
                with open(tmp_path, "wb") as f_out:
                    for chunk in resp.iter_content(chunk_size=65536):
                        if self._closed or self._update_cancel_event.is_set():
                            raise InterruptedError("下载已取消")
                        if not chunk:
                            continue
                        f_out.write(chunk)
                        downloaded += len(chunk)
                        pct = round((downloaded / total_bytes) * 100.0, 1) if total_bytes > 0 else 0.0
                        dl_mb = downloaded / (1024 * 1024)
                        if total_bytes > 0:
                            tot_mb = total_bytes / (1024 * 1024)
                            txt = f"正在下载 v{expected_version}: {pct:.0f}% ({dl_mb:.1f} MB / {tot_mb:.1f} MB)"
                        else:
                            txt = f"正在下载 v{expected_version}: {dl_mb:.1f} MB"
                        self._set_update_download_state(
                            status="downloading",
                            progressPct=min(99.0, pct),
                            downloadedBytes=downloaded,
                            totalBytes=total_bytes,
                            statusText=txt,
                        )

            if downloaded <= 0 or (total_bytes > 0 and downloaded != total_bytes):
                raise RuntimeError("更新包下载不完整，请重试")

            with open(tmp_path, "rb") as f_chk:
                magic = f_chk.read(2)
            if magic != b"MZ":
                raise RuntimeError("下载的更新包格式校验失败（非有效 Windows 可执行文件）")

            os.replace(tmp_path, staged_path)
            log_runtime_event("UPDATE", f"更新包校验通过并已暂存 size={downloaded} target={target_exe}")
            self._apply_staged_update_and_restart(staged_path, target_exe)
        except InterruptedError:
            log_runtime_event("UPDATE", f"更新下载被取消 v{expected_version}", level="WARNING")
            try:
                if os.path.isfile(tmp_path):
                    os.remove(tmp_path)
            except Exception:
                pass
            self._set_update_download_state(status="cancelled", statusText="下载已取消", error="")
        except Exception as e:
            log_runtime_event("UPDATE", f"更新下载失败 v{expected_version} err={e}", level="ERROR")
            try:
                if os.path.isfile(tmp_path):
                    os.remove(tmp_path)
            except Exception:
                pass
            self._set_update_download_state(
                status="error",
                statusText="下载失败",
                error=str(e),
            )

    def _apply_staged_update_and_restart(self, staged_exe: str, target_exe: str):
        """将已校验通过的新版本覆盖到当前目标路径；打包运行时启动静默替换脚本并自动重启"""
        is_frozen = bool(getattr(sys, "frozen", False))
        if not is_frozen:
            os.makedirs(os.path.dirname(target_exe), exist_ok=True)
            os.replace(staged_exe, target_exe)
            self._set_update_download_state(
                status="completed",
                progressPct=100.0,
                statusText=f"更新包已下载并覆盖：{target_exe}",
                filePath=target_exe,
                error="",
            )
            return

        self._set_update_download_state(
            status="installing",
            progressPct=100.0,
            statusText="下载完成，正在覆盖安装并重启...",
            filePath=target_exe,
            error="",
        )
        bat_path = os.path.join(tempfile.gettempdir(), f"discflow_updater_{os.getpid()}.bat")
        script_content = self._build_self_update_script(os.getpid(), staged_exe, target_exe)
        with open(bat_path, "w", encoding="utf-8") as f_bat:
            f_bat.write(script_content)
        creation_flags = getattr(subprocess, "CREATE_NO_WINDOW", 0x08000000)
        subprocess.Popen(["cmd.exe", "/c", bat_path], creationflags=creation_flags, close_fds=True)
        time.sleep(0.35)
        self.exit_app()

    def stop(self):
        """停止播放并复位播放指针"""
        self.player.stop()
        self.elapsed_sec = 0.0
        self._bump_meta()

    def _schedule_ui_push(self):
        """唤醒后台事件推送线程，向前端即时推入增量状态"""
        if hasattr(self, "_push_event"):
            self._push_event.set()

    def _ui_push_worker(self):
        """后台去抖轻量唤醒协程：通知前端主动拉取最新增量状态，避免双通道版本号互踩与大载荷卡顿"""
        while not self._closed:
            self._push_event.wait(timeout=1.0)
            if self._closed:
                break
            if not self._push_event.is_set():
                continue
            time.sleep(0.015)
            self._push_event.clear()
            if self._closed or not self._booted or not self._window:
                continue
            try:
                self._window.evaluate_js("window.triggerImmediatePoll && window.triggerImmediatePoll();")
            except Exception:
                pass

    def _bump_meta(self):
        self._meta_version += 1
        self._schedule_ui_push()

    def _bump_lyrics(self):
        self._lyrics_version += 1
        self._schedule_ui_push()

    def poll_state(
        self,
        client_meta_ver: int = -1,
        client_lyrics_ver: int = -1,
        client_track_index: int = -1,
    ) -> dict:
        """
        供前端 WebView2 定时异步拉取的高性能增量状态接口 (< 0.1ms，无阻塞 I/O、无跨线程 Invoke 死锁)：
        - 每次仅传输 ~180 字节的轻量播放进度与状态字
        - 仅当 _meta_version 变化时才下发 Base64 封面、光驱列表与曲目表
        - 仅当 _lyrics_version 变化时才下发双语 LRC 数组
        """
        meta_ver = self._meta_version
        lyrics_ver = self._lyrics_version

        state = {
            "currentTrackIndex": self.current_track_index,
            "isPlaying": self.player.is_playing(),
            "elapsedSec": round(self.elapsed_sec, 2),
            "durationSec": round(self.duration_sec, 2),
            "isLoading": self.is_loading,
            "statusText": self.status_text,
            "playMode": self.play_mode,
            "volume": self.volume_pct,
            "lyricOffset": round(self._get_current_track_lyric_offset(), 2),
            "metaVersion": meta_ver,
            "lyricsVersion": lyrics_ver,
            "lyricsBatch": dict(self._lyrics_batch),
        }

        if int(client_meta_ver) != meta_ver:
            if self._update_info and self._update_info.get("hasUpdate"):
                state["updateAvailable"] = dict(self._update_info)
            tracks_payload = []
            toc_ref = self.current_toc
            if toc_ref:
                for t in toc_ref.tracks:
                    tracks_payload.append(
                        {
                            "track_number": t.track_number,
                            "title": t.title,
                            "artist": t.artist,
                            "duration_sec": t.duration_sec,
                            "lyricsLocked": t.track_number in self.lyrics_locked_tracks,
                            "lyricsMissed": t.track_number in self.lyrics_missed_tracks,
                        }
                    )
            state.update(
                {
                    "drive": self.current_drive,
                    "drives": list(self._cached_drives),
                    "discId": toc_ref.disc_id if toc_ref else "",
                    "freedbId": toc_ref.freedb_id if toc_ref else "",
                    "albumTitle": self.album_title,
                    "artist": self.artist,
                    "year": self.year,
                    "source": self.source,
                    "coverDataUrl": self.cover_data_url,
                    "tracks": tracks_payload,
                }
            )

        # 歌词下发条件（v1.11.4 修复「首曲歌词不显示、切走再切回才有」）：
        # 除版本号变化外，只要客户端上次渲染的曲目索引与当前曲目不一致，也必须补发一次。
        # 这样即使版本号在轮询间隙被连续自增、前端已提前 ack 到新版本，切歌后也一定会重新拿到歌词。
        if int(client_lyrics_ver) != lyrics_ver or int(client_track_index) != self.current_track_index:
            state["lyrics"] = list(self.current_lyrics)

        return state

    def ui_ready(self):
        with self._lock:
            if self._booted:
                return
            self._booted = True
        if getattr(self, "_saved_maximized", False):
            try:
                hwnd = self._hwnd
                if not hwnd and self._window:
                    native = getattr(self._window, "native", None)
                    if native is not None and not getattr(native, "InvokeRequired", False):
                        hwnd = int(native.Handle.ToInt64()) if hasattr(native, "Handle") else 0
                if hwnd and not ctypes.windll.user32.IsZoomed(hwnd):
                    self._window.maximize()
                    self._is_maximized = True
            except Exception:
                pass
        threading.Thread(target=self._initial_boot, daemon=True).start()
        threading.Thread(target=self._hardware_watcher_loop, daemon=True).start()
        threading.Thread(target=self._ui_push_worker, daemon=True).start()
        threading.Thread(target=self._auto_check_updates_bg, daemon=True).start()

    def _is_ripping(self) -> bool:
        task = getattr(self, "ripper_task", None)
        if not task:
            return False
        try:
            return bool(task.get_progress().is_ripping)
        except Exception:
            return False

    def select_drive(self, drive_letter: str):
        if self._is_ripping():
            return
        if drive_letter:
            threading.Thread(target=self._load_drive_async, args=(drive_letter,), daemon=True).start()

    def rescan_drive(self):
        if self._is_ripping():
            self.status_text = "正在抓轨中，请等待完成或取消后再重新读盘"
            self._bump_meta()
            return
        phys = self._refresh_cached_drives()
        self._non_audio_drives.clear()
        target = ""
        for drv in phys:
            if WindowsCdDriveManager.is_disc_ready(drv):
                target = drv
                break
        if not target:
            if self.current_drive and self.current_drive in phys:
                target = self.current_drive
            elif phys:
                target = phys[0]

        if not target:
            with self._lock:
                self.is_loading = False
                self.status_text = "未检测到可用光驱 · 请连接外置或内置 CD 光驱"
                self._bump_meta()
            return

        self.current_toc = None
        self._bump_meta()
        threading.Thread(target=self._load_drive_async, args=(target,), daemon=True).start()

    def eject_drive(self):
        if self._is_ripping():
            self.status_text = "正在抓轨中，请先取消抓轨再弹出光盘"
            self._bump_meta()
            return
        drv = self.current_drive
        if not drv:
            return
        self._non_audio_drives.discard(drv)
        self._load_token += 1
        self.player.stop()
        self.current_toc = None
        self.is_loading = False
        self.elapsed_sec = 0.0
        self.duration_sec = 0.0
        self.status_text = f"正在弹出光驱 {drv} 托盘..."
        self.album_title = f"光驱 {drv} 托盘已弹出"
        self.artist = "放入新的音频 CD 后将自动识别并播放"
        self.cover_data_url = ""
        self.current_lyrics = []
        self._bump_meta()
        self._bump_lyrics()

        def _eject_worker(target_drv: str):
            WindowsCdDriveManager.eject_disc(target_drv)
            self.status_text = f"已弹出光驱 {target_drv} 托盘 · 等待放入音频 CD"

        threading.Thread(target=_eject_worker, args=(drv,), daemon=True).start()

    def toggle_play_pause(self):
        if self._is_ripping():
            self.status_text = "正在抓轨中，请等待抓轨完成或取消后再播放"
            self._bump_meta()
            return
        if not self.current_toc or not self.current_toc.tracks:
            return
        if not self.player.is_running():
            self._start_track(self.current_track_index)
            return
        playing = self.player.is_playing()
        self.player.set_paused(playing)
        self._schedule_ui_push()

    def prev_track(self):
        if not self.current_toc or not self.current_toc.tracks:
            return
        idx = (self.current_track_index - 1) % len(self.current_toc.tracks)
        self._start_track(idx)

    def next_track(self):
        if not self.current_toc or not self.current_toc.tracks:
            return
        if self.play_mode == "shuffle" and len(self.current_toc.tracks) > 1:
            import random
            choices = [i for i in range(len(self.current_toc.tracks)) if i != self.current_track_index]
            idx = random.choice(choices)
        else:
            idx = (self.current_track_index + 1) % len(self.current_toc.tracks)
        self._start_track(idx)

    def play_track_index(self, index: int):
        if self.current_toc and 0 <= int(index) < len(self.current_toc.tracks):
            self._start_track(int(index))

    def seek_to(self, seconds: float):
        if self._is_ripping():
            return
        target = max(0.0, float(seconds))
        self.elapsed_sec = target
        self.player.seek_seconds(target)

    def set_volume(self, pct: int):
        try:
            v = int(round(max(0.0, min(100.0, float(pct)))))
        except (TypeError, ValueError):
            return
        self.volume_pct = v
        self.player.set_volume(v / 100.0)

    def _get_current_track_lyric_offset(self) -> float:
        if not self.current_toc or not (0 <= self.current_track_index < len(self.current_toc.tracks)):
            return 0.0
        disc_id = self.current_toc.disc_id
        trk = self.current_toc.tracks[self.current_track_index]
        key = f"{disc_id}_{trk.track_number}"
        if key in self.track_lyrics_offsets:
            return float(self.track_lyrics_offsets[key])
        return float(getattr(trk, "lyrics_offset", 0.0))

    def set_track_lyric_offset(self, offset: float) -> bool:
        if not self.current_toc or not (0 <= self.current_track_index < len(self.current_toc.tracks)):
            return False
        disc_id = self.current_toc.disc_id
        trk = self.current_toc.tracks[self.current_track_index]
        key = f"{disc_id}_{trk.track_number}"
        val = round(float(offset), 2)
        self.track_lyrics_offsets[key] = val
        save_user_preferences({"lyricOffsets": self.track_lyrics_offsets})
        if getattr(self.current_toc, "is_local", False):
            self.library_manager.update_track_lyric_offset(disc_id, trk.track_number, val)
        return True

    def _queue_next_track_to_player(self, index: int):
        """计算顺序播放的下一轨，供播放引擎做连续内存预读与无缝跨轨平滑过渡"""
        if not self.current_toc or not self.current_toc.tracks:
            return
        total = len(self.current_toc.tracks)
        if total <= 0:
            return
        if self.play_mode == "one":
            next_idx = index
        elif self.play_mode == "shuffle":
            self.player.set_next_track(None, None, -1)
            return
        else:
            next_idx = (index + 1) % total

        next_trk = self.current_toc.tracks[next_idx]
        self.player.set_next_track(self.current_toc.drive_letter, next_trk, next_idx)

    def _on_player_track_transition(self, next_track: CdTrackInfo, next_index: int):
        """底层播放引擎在无缝跨轨时触发此回调：零延迟推进界面与歌词状态"""
        if self._closed or not self.current_toc:
            return
        self.current_track_index = next_index
        self.duration_sec = next_track.duration_sec
        self.elapsed_sec = 0.0

        if next_track.track_number in self.lyrics_cache:
            self.current_lyrics = self.lyrics_cache[next_track.track_number]
            self._bump_lyrics()
        else:
            self.current_lyrics = []
            self._bump_lyrics()
            threading.Thread(
                target=self._fetch_lyrics_async,
                args=(next_track, False, self._load_token),
                daemon=True,
            ).start()

        self._queue_next_track_to_player(next_index)
        self._save_session_state()
        self._bump_meta()

    def _save_session_state(self):
        """将当前播放的本地唱片与曲目现场写入 preferences.json，供下次无碟启动恢复"""
        try:
            if self.current_toc and getattr(self.current_toc, "is_local", False):
                session_data = {
                    "discId": self.current_toc.disc_id,
                    "trackIndex": self.current_track_index,
                }
                save_user_preferences({"lastSession": session_data})
        except Exception:
            pass

    def _try_resume_last_session(self) -> bool:
        """无碟启动时静默恢复上次播放的本地专辑与曲目（封面与歌词就绪，处于暂停状态）"""
        try:
            prefs = load_user_preferences()
            sess = prefs.get("lastSession")
            if not sess or not isinstance(sess, dict):
                return False
            disc_id = sess.get("discId")
            track_index = int(sess.get("trackIndex", 0))
            if not disc_id:
                return False

            toc = self.library_manager.get_album_toc(disc_id)
            if not toc or not toc.tracks:
                return False

            albums = self.library_manager.list_albums()
            target_album: Optional[LocalAlbumInfo] = None
            for a in albums:
                if a.disc_id == disc_id:
                    target_album = a
                    break

            with self._lock:
                self.current_toc = toc
                self.current_drive = ""
                self.album_title = target_album.title if target_album else (toc.cdtext_album or "Local Album")
                self.artist = target_album.artist if target_album else (toc.cdtext_artist or "Local Artist")
                self.year = target_album.year if target_album else ""
                self.cover_data_url = target_album.cover_data_url if target_album else ""
                self.lyrics_cache.clear()
                self.lyrics_locked_tracks = set()
                self.lyrics_missed_tracks = set()
                self.track_song_ids = {}
                if target_album:
                    for t in target_album.tracks:
                        if t.lyrics:
                            self.lyrics_cache[t.track_number] = t.lyrics
                        if getattr(t, "lyrics_locked", False):
                            self.lyrics_locked_tracks.add(t.track_number)
                        sid = getattr(t, "lyrics_song_id", "") or ""
                        if sid:
                            self.track_song_ids[t.track_number] = {
                                "source": getattr(t, "lyrics_source", "") or "",
                                "song_id": sid,
                            }
                self.is_loading = False

            safe_idx = min(max(0, track_index), len(toc.tracks) - 1)
            self._start_track(safe_idx, autoplay=False)
            self.status_text = f"已就绪：《{self.album_title}》· 按空格开始播放"
            self._bump_meta()
            return True
        except Exception:
            return False

    def set_play_mode(self, mode: str):
        if mode in ("order", "shuffle", "one"):
            self.play_mode = mode
            self._queue_next_track_to_player(self.current_track_index)

    def set_shuffle(self, enabled: bool):
        self.play_mode = "shuffle" if enabled else "order"
        self._queue_next_track_to_player(self.current_track_index)

    def set_repeat_mode(self, mode: str):
        self.play_mode = "one" if mode == "one" else "order"
        self._queue_next_track_to_player(self.current_track_index)

    def start_ripping(self) -> dict:
        with self._lock:
            if not self.current_toc or not self.current_toc.tracks:
                return {"success": False, "message": "当前未放入音频 CD，无法执行抓轨"}
            if getattr(self.current_toc, "is_local", False):
                return {"success": False, "message": "当前已是本地资料库曲目，无需重复抓轨"}
            if self.ripper_task and self.ripper_task.get_progress().is_ripping:
                return {"success": False, "message": "当前已有抓轨任务正在进行中"}

            # 抓轨前安全停播并等待读线程关闭光驱句柄，彻底避免双线程争抢激光头导致降速或 I/O 报错
            self.player.stop()
            try:
                self.player.wait_reader_idle(timeout=1.5)
            except Exception:
                pass

            task = CdRipperTask(
                toc=self.current_toc,
                album_title=self.album_title,
                artist=self.artist,
                year=self.year,
                cover_data_url=self.cover_data_url,
                lyrics_cache=dict(self.lyrics_cache),
                library_mgr=self.library_manager,
            )
            self.ripper_task = task
            threading.Thread(target=task.run, daemon=True).start()
            return {"success": True, "message": "抓轨任务已启动"}

    def cancel_ripping(self) -> dict:
        if self.ripper_task:
            self.ripper_task.cancel()
            return {"success": True, "message": "已取消抓轨"}
        return {"success": False, "message": "当前无抓轨任务"}

    def get_ripping_progress(self) -> dict:
        if not self.ripper_task:
            return asdict(RippingProgress())
        return asdict(self.ripper_task.get_progress())

    def list_local_albums(self) -> list:
        albums = self.library_manager.list_albums(force_refresh=True)
        return [asdict(a) for a in albums]

    def delete_local_album(self, disc_id: str) -> dict:
        """
        从资源库物理删除整张唱片（WAV / 封面 / 元数据一并清除）。
        若该唱片正在播放，先停止播放并等待音频文件句柄释放，避免 Windows 下 rmtree 半途失败留下孤儿文件。
        """
        if not disc_id:
            return {"ok": False, "existed": False, "path": "", "failed": [], "reason": "缺少唱片标识"}

        is_current = bool(
            self.current_toc and getattr(self.current_toc, "disc_id", "") == disc_id
        )
        if is_current:
            try:
                self.player.stop()
            except Exception:
                pass
            # 播放线程为非阻塞复位，需给硬件句柄与 WAV 读取器留出释放时间
            time.sleep(0.35)
            self.current_toc = None
            self.current_track_index = 0
            self.current_lyrics = []
            self.elapsed_sec = 0.0
            self.duration_sec = 0.0
            self._bump_lyrics()

        res = self.library_manager.delete_album_verbose(disc_id)
        if res.get("ok"):
            self._meta_version += 1
        return res

    def update_album_metadata(self, disc_id: str, title: str = "", artist: str = "", year: str = "", track_titles: Optional[dict] = None) -> bool:
        parsed_tracks = None
        if isinstance(track_titles, dict):
            parsed_tracks = {}
            for k, v in track_titles.items():
                try:
                    num = int(k)
                    val = str(v or "").strip()
                    if num > 0 and val:
                        parsed_tracks[num] = val
                except Exception:
                    pass
        res = self.library_manager.update_album_metadata(
            disc_id,
            title=title or None,
            artist=artist or None,
            year=year or None,
            track_titles=parsed_tracks,
        )
        if res:
            if self.current_toc and self.current_toc.disc_id == disc_id:
                if title:
                    self.album_title = title
                if artist:
                    self.artist = artist
                if year is not None:
                    self.year = year
                if parsed_tracks and self.current_toc.tracks:
                    for t in self.current_toc.tracks:
                        if t.track_number in parsed_tracks:
                            t.title = parsed_tracks[t.track_number]
            self._bump_meta()
        return res

    def clear_lyrics_cache(self) -> bool:
        """清空当前内存歌词缓存并让前端重绘（磁盘上的锁定歌词不动）"""
        self.lyrics_cache.clear()
        self.lyrics_missed_tracks.clear()
        self.current_lyrics = []
        self._bump_lyrics()
        self._bump_meta()
        return True

    def clear_all_library_data(self) -> bool:
        """清空整个资料库（磁盘文件一并删除），并重置内存中的播放状态"""
        albums = self.library_manager.list_albums()
        for alb in albums:
            try:
                self.library_manager.delete_album(alb.disc_id)
            except Exception:
                pass
        with self._lock:
            self.player.stop()
            self.current_toc = None
            self.lyrics_cache.clear()
            self.lyrics_locked_tracks = set()
            self.lyrics_missed_tracks = set()
            self.track_song_ids = {}
            self.current_lyrics = []
            self.album_title = "等待放入音频 CD"
            self.artist = ""
            self.year = ""
            self.cover_data_url = ""
            self.status_text = "资料库已清空"
            self._meta_version += 1
        self._bump_lyrics()
        return True

    def update_album_cover(self, disc_id: str, cover_data_url: str) -> bool:
        res = self.library_manager.update_album_cover(disc_id, cover_data_url)
        if res:
            self._meta_version += 1
        return res

    def export_library(self, target_zip_path: str) -> bool:
        return self.library_manager.export_library_zip(target_zip_path)

    def import_library(self, source_zip_path: str) -> bool:
        res = self.library_manager.import_library_zip(source_zip_path)
        if res:
            self._meta_version += 1
        return res

    def get_preferences(self) -> dict:
        return load_user_preferences()

    def save_preferences(self, prefs: dict) -> bool:
        return save_user_preferences(prefs)

    def search_album_candidates_for_current(self, title: str = "", artist: str = "") -> list:
        """按输入（缺省用当前专辑名/艺术家）三源并发检索专辑候选"""
        toc_ref = self.current_toc
        count = len(toc_ref.tracks) if toc_ref else 0
        use_title = (title or "").strip() or (self.album_title or "")
        use_artist = (artist or "").strip() or (self.artist or "")
        if not use_title or use_title in ("Audio CD",) or use_title.startswith("等待"):
            return []
        return search_album_candidates(use_title, use_artist, count)

    def apply_album_candidate(self, cand: dict) -> dict:
        """
        应用用户选定的专辑候选：
        1. 套用专辑名 / 艺术家 / 年份 / 封面；
        2. 按顺序 + 时长对齐写入逐轨曲名；
        3. 记录每轨的歌曲 ID（QQ / 网易云来源），供歌词按 ID 直取；
        4. 本地唱片同步写回 album.json，随后启动整专辑歌词批量套用。
        """
        if not isinstance(cand, dict):
            return {"ok": False, "reason": "候选数据无效"}

        toc_ref = self.current_toc
        # 曲库返回的标题先过一遍清洗：反转义 HTML 实体、去零宽/控制字符、折叠空白
        title = _sanitize_title(cand.get("title"))
        artist = _sanitize_title(cand.get("artist"))
        year = (cand.get("year") or "").strip()
        source = (cand.get("source") or "").strip()
        tracks = cand.get("tracks") or []
        if not title:
            return {"ok": False, "reason": "候选缺少专辑名"}

        # 若选中的候选（如早先缓存或被风控的网易云候选）曲目表为空，尝试从三源检索借用干净曲目表
        if source == "netease" and toc_ref and not tracks and title:
            try:
                fallback_cands = self.search_album_candidates_for_current(title, artist)
                donor = next(
                    (d for d in fallback_cands if d.get("tracks") and not d.get("garbled")),
                    next((d for d in fallback_cands if d.get("tracks")), None),
                )
                if donor:
                    d_src = (donor.get("source") or "").strip()
                    tracks = [
                        {**t, "source": (t.get("source") or d_src)}
                        for t in (donor.get("tracks") or [])
                    ]
            except Exception:
                pass

        disc_id = getattr(toc_ref, "disc_id", "") if toc_ref else ""
        is_local = bool(toc_ref and getattr(toc_ref, "is_local", False))

        track_titles: Dict[int, str] = {}
        track_artists: Dict[int, str] = {}
        song_ids: Dict[int, dict] = {}
        skipped_garbled = 0
        # 本地同名曲目（同一张碟出现两首一模一样的名字）说明本地元数据本身就不可信，
        # 这种情况下不做 CJK 保护，让曲库的准确曲名覆盖掉
        local_name_counts: Dict[str, int] = {}
        if toc_ref:
            for t in toc_ref.tracks:
                key = (t.title or "").strip()
                local_name_counts[key] = local_name_counts.get(key, 0) + 1
        if toc_ref and tracks:
            durations = [t.duration_sec for t in toc_ref.tracks]
            mapping = match_tracks_by_duration(durations, tracks)
            for idx, c in mapping.items():
                if not (0 <= idx < len(toc_ref.tracks)):
                    continue
                trk = toc_ref.tracks[idx]
                nm = _sanitize_title(c.get("title"))
                local_nm = trk.title or ""
                # 曲库常把日文曲名存成英文（茎 → Stem）：本地是 CJK、候选是纯拉丁时保留本地曲名。
                # 但如果本地曲名本身就是乱码（ソ━膝）、或者本地同名曲目出现多次（元数据不可信），
                # 就别再护着它了，宁可换成拉丁名。
                if (
                    nm
                    and not _looks_garbled(local_nm)
                    and local_name_counts.get(local_nm.strip(), 0) <= 1
                    and _has_cjk(local_nm)
                    and not _has_cjk(nm)
                ):
                    nm = ""
                # 候选曲名本身是乱码（━ 之类的误解码产物）时一律不覆盖本地曲名
                if nm and _looks_garbled(nm):
                    nm = ""
                    skipped_garbled += 1
                if nm:
                    track_titles[trk.track_number] = nm
                # 专辑艺术家变更时同步曲目艺术家，保证「专辑作者 / 曲目作者」一致
                if artist:
                    track_artists[trk.track_number] = artist
                sid = (c.get("song_id") or "").strip()
                if sid:
                    trk_src = (c.get("source") or source or "").strip()
                    song_ids[trk.track_number] = {"source": trk_src, "song_id": sid}

        cover_url_remote = (cand.get("cover_url") or "").strip()
        cover_data_url = ""
        if cover_url_remote:
            cover_bytes = download_image_bytes(cover_url_remote)
            if cover_bytes:
                cover_data_url = _bytes_to_data_url(cover_bytes)

        with self._lock:
            self.album_title = title
            if artist:
                self.artist = artist
            self.year = year
            self.source = f"{source or '手动'} 专辑匹配"
            if cover_data_url:
                self.cover_data_url = cover_data_url
            if toc_ref:
                for trk in toc_ref.tracks:
                    if trk.track_number in track_titles:
                        trk.title = track_titles[trk.track_number]
                    if trk.track_number in track_artists:
                        trk.artist = track_artists[trk.track_number]
            self.status_text = f"已套用专辑：《{self.album_title}》— {self.artist}"
            self._bump_meta()

        if song_ids:
            self.track_song_ids.update(song_ids)

        if is_local and disc_id:
            try:
                self.library_manager.update_album_metadata(
                    disc_id,
                    title=self.album_title,
                    artist=self.artist or None,
                    year=self.year or None,
                    track_titles=track_titles or None,
                    track_artists=track_artists or None,
                )
            except Exception:
                pass
            if cover_data_url:
                try:
                    self.library_manager.update_album_cover(disc_id, cover_data_url)
                except Exception:
                    pass
            for tn, info in song_ids.items():
                try:
                    self.library_manager.update_track_song_id(disc_id, tn, info["source"], info["song_id"])
                except Exception:
                    pass

        # 曲名/专辑已重新匹配：清理被新专辑覆盖或尚未拥有逐字时间轴的旧缓存与锁定，保证整碟刷新
        cur_tn = None
        if toc_ref and 0 <= self.current_track_index < len(toc_ref.tracks):
            cur_tn = toc_ref.tracks[self.current_track_index].track_number
        track_nums_to_reset = set(track_titles.keys()) | set(song_ids.keys())
        if toc_ref:
            for t in toc_ref.tracks:
                cached_lyr = self.lyrics_cache.get(t.track_number)
                has_words = bool(cached_lyr and any(isinstance(ln, dict) and ln.get("words") for ln in cached_lyr))
                if not has_words or not self._lyrics_quality_ok(cached_lyr):
                    track_nums_to_reset.add(t.track_number)
        for tn in list(self.lyrics_cache.keys()):
            if tn in track_nums_to_reset or tn not in self.lyrics_locked_tracks:
                self.lyrics_cache.pop(tn, None)
                self.lyrics_locked_tracks.discard(tn)
        for tn in track_nums_to_reset:
            self.lyrics_locked_tracks.discard(tn)
            self.lyrics_missed_tracks.discard(tn)
        if cur_tn is not None and cur_tn not in self.lyrics_cache:
            self.current_lyrics = []
        self._bump_lyrics()

        try:
            batch_info = self.start_album_lyrics_batch()
        except Exception:
            batch_info = {"ok": False}

        return {
            "ok": True,
            "albumTitle": self.album_title,
            "artist": self.artist,
            "year": self.year,
            "trackCount": len(track_titles),
            "songIdCount": len(song_ids),
            "skippedGarbled": skipped_garbled,
            "lyricsBatchStarted": bool(batch_info.get("ok")),
            "source": self.source,
        }

    def apply_manual_metadata(self, title: str, artist: str = "", year: str = "") -> dict:
        """兼容入口：按专辑名检索并自动应用最佳候选"""
        title = (title or "").strip()
        artist = (artist or "").strip()
        if not title:
            return {"ok": False, "reason": "专辑名称不能为空"}
        cands = self.search_album_candidates_for_current(title, artist)
        if not cands:
            return {
                "ok": False,
                "matched": False,
                "reason": "没有找到匹配的专辑，请换用更准确的专辑名，或补上艺术家后再试。",
            }
        # 优先取曲名干净的候选；全部带乱码时才退回第一条
        best = next((c for c in cands if not c.get("garbled")), cands[0])
        res = self.apply_album_candidate(best)
        res["matched"] = True
        return res

    # ------------------------------------------------------------------
    # 逐轨歌词手动匹配
    # ------------------------------------------------------------------
    def _find_track(self, track_number: int):
        if not self.current_toc:
            return None
        try:
            want = int(track_number)
        except Exception:
            return None
        for t in self.current_toc.tracks:
            if int(t.track_number) == want:
                return t
        return None

    def _persist_track_lyrics(self, track_number: int, lines: List[dict], source: str = "",
                              song_id: str = "", locked: bool = False, clear_lock: bool = False) -> bool:
        toc_ref = self.current_toc
        if not toc_ref or not getattr(toc_ref, "is_local", False):
            return False
        disc_id = getattr(toc_ref, "disc_id", "")
        if not disc_id:
            return False
        try:
            return self.library_manager.update_track_lyrics(
                disc_id, track_number, lines,
                source=source, song_id=song_id, locked=locked, clear_lock=clear_lock,
            )
        except Exception:
            return False

    def _is_current_track(self, track_number: int) -> bool:
        toc_ref = self.current_toc
        if not toc_ref or not (0 <= self.current_track_index < len(toc_ref.tracks)):
            return False
        return int(toc_ref.tracks[self.current_track_index].track_number) == int(track_number)

    def search_track_lyric_candidates(
        self, track_number: int, title: str = "", artist: str = ""
    ) -> list:
        """三源检索指定曲目的歌词候选，供用户挑选"""
        trk = self._find_track(track_number)
        if not trk:
            return []
        use_title = (title or "").strip() or (trk.title or "")
        use_artist = (artist or "").strip() or (trk.artist or "")
        return search_lyric_candidates(use_title, use_artist, trk.duration_sec, limit=8)

    def apply_track_lyrics(
        self, track_number: int, source: str, song_id: str,
        title: str = "", artist: str = "", duration: float = 0.0,
    ) -> dict:
        """应用用户选定的歌词，并锁定该曲目，自动流程不再覆盖"""
        trk = self._find_track(track_number)
        if not trk:
            return {"ok": False, "reason": "找不到该曲目"}

        cand = {
            "source": source,
            "song_id": str(song_id or ""),
            "title": (title or trk.title or "").strip(),
            "artist": (artist or trk.artist or "").strip(),
            "duration_sec": float(duration or trk.duration_sec or 0),
        }
        lines = fetch_lyrics_for_candidate(cand)
        if not lines:
            return {"ok": False, "reason": "该来源没有返回可用歌词，换一条候选试试。"}

        tn = int(trk.track_number)
        self.lyrics_cache[tn] = lines
        self.lyrics_locked_tracks.add(tn)
        self.lyrics_missed_tracks.discard(tn)
        self._persist_track_lyrics(tn, lines, source=source, song_id=str(song_id or ""), locked=True)

        if self._is_current_track(tn):
            self.current_lyrics = lines
            self._bump_lyrics()
        self._bump_meta()

        return {
            "ok": True,
            "lineCount": len(lines),
            "source": source,
            "hasTranslation": any(ln.get("translation") for ln in lines),
        }

    def clear_track_lyrics(self, track_number: int) -> dict:
        """清空指定曲目的歌词并解除锁定"""
        trk = self._find_track(track_number)
        if not trk:
            return {"ok": False, "reason": "找不到该曲目"}
        tn = int(trk.track_number)
        self.lyrics_cache.pop(tn, None)
        self.lyrics_locked_tracks.discard(tn)
        self._persist_track_lyrics(tn, [], clear_lock=True)
        if self._is_current_track(tn):
            self.current_lyrics = []
            self._bump_lyrics()
        return {"ok": True}

    def auto_match_track_lyrics(self, track_number: int) -> dict:
        """解除锁定并按曲名重新自动匹配一次"""
        trk = self._find_track(track_number)
        if not trk:
            return {"ok": False, "reason": "找不到该曲目"}
        tn = int(trk.track_number)
        self.lyrics_locked_tracks.discard(tn)
        self.lyrics_cache.pop(tn, None)

        lines = lookup_track_lyrics(
            trk.title, trk.artist, trk.duration_sec, getattr(trk, "builtin_lrc", "") or ""
        )
        if lines:
            self.lyrics_cache[tn] = lines
            self.lyrics_missed_tracks.discard(tn)
            self._persist_track_lyrics(tn, lines, clear_lock=True)
        else:
            self._persist_track_lyrics(tn, [], clear_lock=True)

        if self._is_current_track(tn):
            self.current_lyrics = lines
            self._bump_lyrics()
        self._bump_meta()

        return {"ok": bool(lines), "lineCount": len(lines)}

    # ------------------------------------------------------------------
    # 整专辑歌词批量套用
    # ------------------------------------------------------------------
    def start_album_lyrics_batch(self, force_refresh: bool = False) -> dict:
        """按当前专辑每一轨的曲名，批量检索并套用歌词（后台执行，带进度；支持强制重刷）"""
        if self._lyrics_batch.get("running"):
            return {"ok": False, "reason": "已有批量任务在进行中"}
        toc_ref = self.current_toc
        if not toc_ref or not toc_ref.tracks:
            return {"ok": False, "reason": "当前没有可处理的曲目"}

        tracks = [t for t in toc_ref.tracks if not getattr(t, "is_data_track", False)]
        if not tracks:
            return {"ok": False, "reason": "当前没有音频曲目"}

        self._lyrics_batch = {"running": True, "done": 0, "total": len(tracks), "matched": 0, "missed": []}
        threading.Thread(
            target=self._run_album_lyrics_batch,
            args=(toc_ref, tracks, bool(force_refresh)),
            daemon=True,
        ).start()
        return {"ok": True, "total": len(tracks)}

    def _run_album_lyrics_batch(self, toc_ref, tracks, force_refresh: bool = False) -> None:
        """
        并发为每轨取词：
        - 若该轨已绑定歌曲 ID（来自专辑匹配），直接按 ID 取词，不再搜索（快且不会配错）；
        - 否则退回三源检索，并尽可能补齐逐字时间轴；
        - 当 force_refresh=True 时忽略历史锁定与缓存，强制全碟升级刷新。
        """
        from concurrent.futures import ThreadPoolExecutor

        disc_id = getattr(toc_ref, "disc_id", "")
        is_local = bool(getattr(toc_ref, "is_local", False))
        total = len(tracks)
        done = 0
        matched = 0
        missed: List[int] = []

        def _fetch_lines(trk):
            sid = self.track_song_ids.get(trk.track_number) or {}
            if sid.get("song_id"):
                lines = fetch_lyrics_for_candidate(
                    {"source": sid.get("source") or "", "song_id": sid["song_id"]}
                )
                if lines:
                    if not any(isinstance(ln, dict) and ln.get("words") for ln in lines):
                        lines = enrich_lyrics_with_word_timings(
                            trk.title, trk.artist, trk.duration_sec, lines
                        )
                    return lines, {"source": sid.get("source") or "", "song_id": sid["song_id"]}
            try:
                direct_lines = lookup_track_lyrics(trk.title, trk.artist, trk.duration_sec)
                if direct_lines:
                    if not any(isinstance(ln, dict) and ln.get("words") for ln in direct_lines):
                        direct_lines = enrich_lyrics_with_word_timings(
                            trk.title, trk.artist, trk.duration_sec, direct_lines
                        )
                    return direct_lines, {}
            except Exception:
                pass
            return [], {}

        def _work(trk):
            existing = self.lyrics_cache.get(trk.track_number)
            if not force_refresh:
                if trk.track_number in self.lyrics_locked_tracks:
                    has_words = bool(existing and any(isinstance(ln, dict) and ln.get("words") for ln in existing))
                    if existing and (has_words or self._lyrics_quality_ok(existing)):
                        return (trk, [], {}, "locked")
                if existing and self._lyrics_quality_ok(existing):
                    has_words = bool(any(isinstance(ln, dict) and ln.get("words") for ln in existing))
                    if has_words:
                        return (trk, [], {}, "ok")
            lines, info = _fetch_lines(trk)
            if lines:
                return (trk, lines, info, "hit")
            if existing:
                return (trk, [], {}, "ok")
            return (trk, [], {}, "miss")

        ordered_tracks = sorted(
            tracks,
            key=lambda t: (0 if self._is_current_track(t.track_number) else 1, int(t.track_number)),
        )
        try:
            with ThreadPoolExecutor(max_workers=4) as pool:
                for trk, lines, info, status in pool.map(_work, ordered_tracks):
                    if status == "ok":
                        matched += 1
                    if status == "hit" and lines:
                        tn = int(trk.track_number)
                        self.lyrics_cache[tn] = lines
                        self.lyrics_locked_tracks.add(tn)
                        if info.get("song_id"):
                            self.track_song_ids[tn] = info
                        if is_local and disc_id:
                            self._persist_track_lyrics(
                                tn, lines,
                                source=str(info.get("source") or ""),
                                song_id=str(info.get("song_id") or ""),
                                locked=True,
                            )
                        matched += 1
                        if self._is_current_track(tn):
                            self.current_lyrics = lines
                            self._bump_lyrics()
                    elif status == "miss":
                        # 批量对不上的轨道单独记账，前端会在曲目行上标出来，
                        # 引导用户用行内「词」按钮逐轨手动指定（专辑优先、单曲兜底）
                        missed.append(int(trk.track_number))
                    done += 1
                    self._lyrics_batch = {
                        "running": done < total,
                        "done": done,
                        "total": total,
                        "matched": matched,
                        "missed": list(missed),
                    }
                    self._schedule_ui_push()
        finally:
            self.lyrics_missed_tracks = set(missed)
            self._lyrics_batch = {
                "running": False,
                "done": done,
                "total": total,
                "matched": matched,
                "missed": list(missed),
            }
            if missed:
                self.status_text = (
                    f"整专辑歌词匹配完成：{matched}/{total} 首，"
                    f"{len(missed)} 首未命中，可点曲目行的「词」逐轨指定"
                )
            else:
                self.status_text = f"整专辑歌词匹配完成：{matched}/{total} 首"
            self._bump_meta()
            self._bump_lyrics()

    def get_library_dir(self) -> str:
        try:
            return os.path.abspath(self.library_manager.base_dir)
        except Exception:
            return os.path.abspath(LIBRARY_DIR)

    def open_library_folder(self) -> dict:
        """在 Windows 资源管理器中打开资源库存储目录"""
        target = self.get_library_dir()
        try:
            os.makedirs(target, exist_ok=True)
        except Exception:
            return {"ok": False, "path": target}
        try:
            if hasattr(os, "startfile"):
                os.startfile(target)  # type: ignore[attr-defined]
                return {"ok": True, "path": target}
        except Exception:
            pass
        try:
            import subprocess

            subprocess.Popen(["explorer", os.path.normpath(target)])
            return {"ok": True, "path": target}
        except Exception:
            return {"ok": False, "path": target}

    def open_external_url(self, url: str) -> dict:
        """在系统默认浏览器中打开外部链接"""
        try:
            import webbrowser
            webbrowser.open(url)
            return {"ok": True, "url": url}
        except Exception as e:
            try:
                if hasattr(os, "startfile"):
                    os.startfile(url)
                    return {"ok": True, "url": url}
            except Exception:
                pass
            return {"ok": False, "error": str(e)}

    def play_local_album(self, disc_id: str) -> bool:
        toc = self.library_manager.get_album_toc(disc_id)
        if not toc:
            return False

        albums = self.library_manager.list_albums()
        target_album: Optional[LocalAlbumInfo] = None
        for a in albums:
            if a.disc_id == disc_id:
                target_album = a
                break

        with self._lock:
            self._load_token += 1
            self.player.stop()
            self.current_toc = toc
            self.current_drive = ""
            self.album_title = target_album.title if target_album else (toc.cdtext_album or "Local Album")
            self.artist = target_album.artist if target_album else (toc.cdtext_artist or "Local Artist")
            self.year = target_album.year if target_album else ""
            self.cover_data_url = target_album.cover_data_url if target_album else ""
            self.lyrics_cache.clear()
            self.lyrics_locked_tracks = set()
            self.lyrics_missed_tracks = set()
            self.track_song_ids = {}
            if target_album:
                for t in target_album.tracks:
                    if t.lyrics:
                        self.lyrics_cache[t.track_number] = t.lyrics
                    if getattr(t, "lyrics_locked", False):
                        self.lyrics_locked_tracks.add(t.track_number)
                    sid = getattr(t, "lyrics_song_id", "") or ""
                    if sid:
                        self.track_song_ids[t.track_number] = {
                            "source": getattr(t, "lyrics_source", "") or "",
                            "song_id": sid,
                        }
            self.status_text = f"正在离线播放黑胶资料库: 《{self.album_title}》"
            self.is_loading = False
            self._bump_meta()
            self._bump_lyrics()

        self._start_track(0)
        threading.Thread(
            target=self._prefetch_lyrics_async,
            args=(self._load_token,),
            daemon=True,
        ).start()
        return True

    def _refresh_cached_drives(self) -> List[str]:
        phys = WindowsCdDriveManager.list_physical_cdrom_drives()
        if phys != self._cached_drives:
            self._cached_drives = phys
            self._bump_meta()
        return phys

    def _initial_boot(self):
        self._boot_scanning = True
        try:
            phys = self._refresh_cached_drives()
            target = ""
            if phys:
                # 启动时部分外置/休眠光驱首次 CHECK_VERIFY 可能返回 False，短暂重试并尝试读取 TOC 唤醒光驱
                for attempt in range(5):
                    for drv in phys:
                        if WindowsCdDriveManager.is_disc_ready(drv):
                            target = drv
                            break
                        try:
                            toc = WindowsCdDriveManager.read_toc(drv)
                            if toc is not None and len(toc.tracks) > 0:
                                target = drv
                                break
                        except Exception:
                            pass
                    if target or attempt == 4:
                        break
                    time.sleep(0.5)

            if target:
                self.is_loading = True
                threading.Thread(target=self._load_drive_async, args=(target,), daemon=True).start()
            else:
                # 无物理光盘插入时，若启动预恢复已成功则不重复加载，仅异步补取缺失歌词
                if getattr(self, "_initial_session_resumed", False) and self.current_toc:
                    restored = True
                    threading.Thread(target=self._prefetch_lyrics_async, args=(self._load_token,), daemon=True).start()
                else:
                    restored = self._try_resume_last_session()
                if not restored:
                    with self._lock:
                        self.is_loading = False
                        self.current_toc = None
                        self.current_drive = ""
                        if phys:
                            self.status_text = f"光驱 {phys[0]} 已就绪 · 请放入音频 CD 光盘"
                            self.album_title = f"等待光驱 {phys[0]} 放入 CD"
                        else:
                            self.status_text = "未检测到可用光驱 · 请连接外置或内置 CD 光驱"
                            self.album_title = "等待放入音频 CD"
                        self.artist = "放入音频 CD 或从「资料库」选择唱片即可播放"
                        self.cover_data_url = ""
                        self._bump_meta()
        finally:
            self._boot_scanning = False

    def _hardware_watcher_loop(self):
        while not self._closed:
            time.sleep(1.8)
            if self._closed:
                break
            # 若当前正在启动扫描或高优先级加载读盘，暂缓该轮巡检，避免双线程并发打断 _load_token
            if self._boot_scanning or self.is_loading:
                continue

            try:
                # 关键保护：当前若正在活跃播放本地黑胶资料库专辑（is_local=True），
                # 绝不受物理光驱有盘/无盘巡检影响；若处于未起播就绪状态且放入物理CD，允许切入
                if self.current_toc is not None and getattr(self.current_toc, "is_local", False):
                    if self.player.is_running():
                        continue

                phys = self._refresh_cached_drives()
                if self._is_ripping():
                    self._watcher_miss_count.clear()
                    continue
                if not phys:
                    if self.current_toc and not getattr(self.current_toc, "is_local", False):
                        self._handle_disc_removed(self.current_drive)
                    continue

                for p_drv in phys:
                    # 关键保护：当物理光驱正在活跃读取 CD-DA 原始 PCM 扇区播放时，
                    # 绝不开启新句柄发送 IOCTL 检查，防止外置 USB 光驱因总线争夺产生杂音或卡顿
                    if (
                        self.current_toc is not None
                        and not self.current_toc.is_simulated
                        and self.current_toc.drive_letter == p_drv
                        and self.player.is_running()
                    ):
                        self._watcher_miss_count[p_drv] = 0
                        continue

                    ready = WindowsCdDriveManager.is_disc_ready(p_drv)
                    if ready:
                        self._watcher_miss_count[p_drv] = 0
                        if p_drv in self._non_audio_drives:
                            continue
                        if (
                            self.current_toc is None
                            or self.current_toc.drive_letter != p_drv
                        ):
                            # 如果该光驱正在异步加载，不要重复发起触发
                            if self.current_drive == p_drv and self.is_loading:
                                continue
                            threading.Thread(
                                target=self._load_drive_async,
                                args=(p_drv,),
                                daemon=True,
                            ).start()
                            break
                    else:
                        # 部分 USB 光驱在休眠/刚插入时 CHECK_VERIFY 返回 False 但 read_toc 可唤醒读出
                        if (
                            p_drv not in self._non_audio_drives
                            and (self.current_toc is None or self.current_toc.drive_letter != p_drv)
                            and (self._watcher_miss_count.get(p_drv, 0) % 2 == 0)
                        ):
                            try:
                                probe_toc = WindowsCdDriveManager.read_toc(p_drv)
                                if probe_toc is not None and len(probe_toc.tracks) > 0:
                                    self._watcher_miss_count[p_drv] = 0
                                    threading.Thread(
                                        target=self._load_drive_async,
                                        args=(p_drv,),
                                        daemon=True,
                                    ).start()
                                    break
                            except Exception:
                                pass
                        # 光盘已取出或未就绪时清除非音频标记，等待下次放盘重新识别
                        self._non_audio_drives.discard(p_drv)
                        # 物理防抖：外置 USB 光驱在寻道或刚放入时可能偶发瞬态未就绪
                        # 只有连续 3 次巡检 (约 5.4 秒) 均明确未就绪，且当前载入了该光驱，才判定为退盘
                        self._watcher_miss_count[p_drv] = self._watcher_miss_count.get(p_drv, 0) + 1
                        if (
                            self.current_toc is not None
                            and self.current_toc.drive_letter == p_drv
                            and self._watcher_miss_count[p_drv] >= 3
                        ):
                            self._handle_disc_removed(p_drv)
                            break
            except Exception:
                pass

    def _handle_disc_removed(self, drive_letter: str):
        self.player.stop()
        with self._lock:
            self.current_toc = None
            self.is_loading = False
            self.elapsed_sec = 0.0
            self.duration_sec = 0.0
            self.status_text = f"光驱 {drive_letter} 中光盘已取出 · 等待放入 CD"
            self.album_title = f"等待光驱 {drive_letter} 放入 CD"
            self.artist = "放入音频 CD 后约 3~5 秒自动识别专辑、封面与双语歌词"
            self.cover_data_url = ""
            self.current_lyrics = []
            self._bump_meta()
            self._bump_lyrics()

    def _load_drive_async(self, drive_letter: str):
        if not drive_letter:
            with self._lock:
                self.is_loading = False
                self.status_text = "未检测到可用光驱 · 请连接外置或内置 CD 光驱"
                self._bump_meta()
            return

        with self._lock:
            self._load_token += 1
            my_token = self._load_token
            self.is_loading = True
            self.current_drive = drive_letter

        self.player.stop()
        self.lyrics_cache.clear()
        self.lyrics_locked_tracks = set()
        self.lyrics_missed_tracks = set()
        self.track_song_ids = {}
        self.current_lyrics = []
        self.status_text = f"正在读取光驱 {drive_letter} 引导区 TOC..."
        self._bump_meta()
        self._bump_lyrics()

        toc: Optional[CdDiscToc] = None
        try:
            max_attempts = 12
            for attempt in range(max_attempts):
                if my_token != self._load_token or self._closed:
                    return

                # 优先直接尝试读 TOC (外置光驱旋转就绪时直接命中，省去冗余就绪等待)
                toc = WindowsCdDriveManager.read_toc(drive_letter)
                if toc and toc.tracks:
                    break

                if attempt < max_attempts - 1:
                    self.status_text = f"光驱 {drive_letter} 正在旋转启动 ({attempt + 1}/{max_attempts})..."
                    self._bump_meta()
                    time.sleep(0.8)

            if my_token != self._load_token or self._closed:
                return

            if not toc or not toc.tracks:
                log_runtime_event("DRIVE", f"光驱 {drive_letter} 未检测到有效音频 TOC")
                if WindowsCdDriveManager.is_disc_ready(drive_letter):
                    self._non_audio_drives.add(drive_letter)
                with self._lock:
                    if my_token == self._load_token:
                        self.current_toc = None
                        self.is_loading = False
                        self.elapsed_sec = 0.0
                        self.duration_sec = 0.0
                        self.status_text = f"光驱 {drive_letter} 已就绪 · 请放入音频 CD 光盘"
                        self.album_title = f"等待光驱 {drive_letter} 放入 CD"
                        self.artist = "放入音频 CD 后约 3~5 秒自动识别专辑、封面与双语歌词"
                        self.cover_data_url = ""
                        self._bump_meta()
                return

            audio_indices = [i for i, t in enumerate(toc.tracks) if not getattr(t, "is_data_track", False)]
            if not audio_indices:
                self._non_audio_drives.add(drive_letter)
                with self._lock:
                    if my_token == self._load_token:
                        self.current_toc = None
                        self.is_loading = False
                        self.elapsed_sec = 0.0
                        self.duration_sec = 0.0
                        self.status_text = f"光驱 {drive_letter} 中的光盘不含标准音频 CD (CD-DA) 音轨"
                        self.album_title = f"非音频 CD ({drive_letter})"
                        self.artist = "请更换标准音频 CD 光盘"
                        self.cover_data_url = ""
                        self._bump_meta()
                return

            with self._lock:
                if my_token != self._load_token or self._closed:
                    return
                self.current_toc = toc
                self.album_title = toc.cdtext_album or "Audio CD"
                self.artist = toc.cdtext_artist or f"DiscID {toc.disc_id[:10]}"
                self.year = ""
                self.cover_data_url = ""
                self.status_text = f"已就绪 ({drive_letter}) · {len(audio_indices)} 首音轨 · 正在匹配封面与元数据..."
                self.is_loading = False
                self._bump_meta()

            # 「放入光盘自动播放」可在设置里关掉；关掉时只读元数据不出声
            try:
                auto_play = bool(load_user_preferences().get("autoPlay", True))
            except Exception:
                auto_play = True
            self._start_track(audio_indices[0], autoplay=auto_play)
            threading.Thread(target=self._fetch_metadata_async, args=(toc, my_token), daemon=True).start()
        except Exception as e:
            with self._lock:
                if my_token == self._load_token:
                    self.is_loading = False
                    self.status_text = f"读取光驱 {drive_letter} 异常: {e}"
                    self._bump_meta()
        finally:
            # 终极安全网：确保无论发生什么，is_loading 绝不会永久处于 True
            with self._lock:
                if my_token == self._load_token and self.is_loading:
                    self.is_loading = False
                    self._bump_meta()

    @staticmethod
    def _is_placeholder_track(title: str, artist: str) -> bool:
        raw_art = (artist or "").strip()
        placeholder_art = (not raw_art) or raw_art in ("未知艺术家", "Audio CD") or raw_art.startswith("DiscID")
        return bool(re.match(r"^Track\s*\d+$", title or "") and placeholder_art)

    def _apply_metadata_to_state(self, meta: AlbumMetadataResult, my_token: int):
        if self._closed or my_token != self._load_token:
            return
        if not self.current_toc or self.current_toc.disc_id != meta.disc_id:
            return

        prev_cur_sig = ""
        if 0 <= self.current_track_index < len(self.current_toc.tracks):
            t0 = self.current_toc.tracks[self.current_track_index]
            prev_cur_sig = f"{t0.title}|{t0.artist}"

        self.album_title = meta.album_title
        self.artist = meta.artist
        self.year = meta.year
        self.source = meta.matched_source
        if meta.cover_data_url:
            self.cover_data_url = meta.cover_data_url
        self.status_text = f"{meta.album_title} — {meta.artist} ({meta.matched_source})"

        for trk in self.current_toc.tracks:
            if trk.track_number in meta.track_titles:
                trk.title = meta.track_titles[trk.track_number]
            if trk.track_number in meta.track_artists:
                trk.artist = meta.track_artists[trk.track_number]

        self._bump_meta()

        # 元数据刚匹配到位时，立即为当前正在播放的音轨（如第 1 首）单独高优拉取歌词，
        # 避免被整张专辑 10+ 首批量预取阻塞等待。
        if 0 <= self.current_track_index < len(self.current_toc.tracks):
            cur_trk = self.current_toc.tracks[self.current_track_index]
            if not self._is_placeholder_track(cur_trk.title, cur_trk.artist):
                cur_sig = f"{cur_trk.title}|{cur_trk.artist}"
                cur_cached = self.lyrics_cache.get(cur_trk.track_number)
                need_fetch = (
                    (cur_trk.track_number not in self.lyrics_cache)
                    or (not self._lyrics_quality_ok(cur_cached))
                    or (cur_sig != prev_cur_sig and not self.current_lyrics)
                )
                fetch_key = (my_token, cur_trk.track_number, cur_trk.title, cur_trk.artist)
                if need_fetch and fetch_key not in self._lyrics_fetching_keys:
                    self._lyrics_fetching_keys.add(fetch_key)
                    threading.Thread(
                        target=self._fetch_lyrics_async,
                        args=(cur_trk, True, my_token, fetch_key),
                        daemon=True,
                    ).start()

    def _fetch_metadata_async(self, toc: CdDiscToc, my_token: int):
        def _on_partial(partial_meta: AlbumMetadataResult):
            # 仅先应用文字元数据并高优拉取当前播放曲目（如 Track 1）歌词，
            # 暂不在回调内启动整碟批量抓词，避免与封面下载争抢并发导致限流超时。
            self._apply_metadata_to_state(partial_meta, my_token)

        meta: AlbumMetadataResult = lookup_album_metadata(toc, on_partial=_on_partial)

        # 弱网下 MusicBrainz 偶发超时，首次没匹配上就补一次重试。
        # 否则界面会一直停在「Audio CD / Track 01」，用户会以为光盘读不出来。
        # 失败结果不会写进 _METADATA_CACHE，所以重试是真正重新联网查询。
        if (
            (not meta.album_title or meta.album_title == "Audio CD")
            and not self._closed
            and my_token == self._load_token
        ):
            time.sleep(2.5)
            if not self._closed and my_token == self._load_token:
                meta = lookup_album_metadata(toc, on_partial=_on_partial)

        self._apply_metadata_to_state(meta, my_token)

        # 封面补抓：标题匹配上了但封面源超时，界面会一直停在占位图标上。
        # 这里异步再试一次，成功了就悄悄补上。
        if (
            not meta.cover_data_url
            and meta.album_title
            and meta.album_title != "Audio CD"
            and not self._closed
            and my_token == self._load_token
        ):
            threading.Thread(
                target=self._retry_cover_async,
                args=(meta.disc_id, meta.album_title, meta.artist, my_token),
                daemon=True,
            ).start()

        if self.current_toc and not self._closed and my_token == self._load_token:
            threading.Thread(
                target=self._prefetch_lyrics_async,
                args=(my_token,),
                daemon=True,
            ).start()

    def _retry_cover_async(self, disc_id: str, album_title: str, artist: str, my_token: int):
        """封面补抓：稍等片刻再联网取一次，成功就更新封面"""
        time.sleep(2.0)
        if self._closed or my_token != self._load_token:
            return
        data_url = refetch_album_cover(album_title, artist)
        if not data_url or self._closed or my_token != self._load_token:
            return
        if not self.current_toc or self.current_toc.disc_id != disc_id:
            return
        if self.cover_data_url:
            return  # 期间已经被别的路径补上了
        update_cached_cover(disc_id, data_url)
        self.cover_data_url = data_url
        self._bump_meta()

    def _start_track(self, index: int, autoplay: bool = True):
        if self._is_ripping():
            return
        if not self.current_toc or not (0 <= index < len(self.current_toc.tracks)):
            return

        self.current_track_index = index
        trk = self.current_toc.tracks[index]
        self.duration_sec = trk.duration_sec
        self.elapsed_sec = 0.0

        if trk.track_number in self.lyrics_cache:
            self.current_lyrics = self.lyrics_cache[trk.track_number]
            self._bump_lyrics()
        else:
            self.current_lyrics = []
            self._bump_lyrics()
            # 切到任何有真实曲名但未缓存歌词的曲目都立即补取；
            # 若仍是占位 Track 01，则等待 _apply_metadata_to_state 元数据就绪后统一高优直取。
            if not self._is_placeholder_track(trk.title, trk.artist):
                threading.Thread(
                    target=self._fetch_lyrics_async,
                    args=(trk, False, self._load_token),
                    daemon=True,
                ).start()

        # 计算顺序播放的下一轨，供播放引擎做连续内存预读与无缝跨轨过渡
        self._queue_next_track_to_player(index)

        # 记录本地专辑播放现场 (Session Resume)
        self._save_session_state()

        # 关闭「放入光盘自动播放」时只准备好曲目与歌词，等用户点播放键再出声
        if autoplay:
            self.player.load_and_play(self.current_toc.drive_letter, trk, track_index=index)
        else:
            self.status_text = f"已就绪：《{self.album_title}》· 按播放键或空格开始"
            self._bump_meta()

    def _fetch_lyrics_async(self, trk, force_refresh: bool = False, my_token: int = 0, _fetch_key=None):
        try:
            if self._closed or (my_token and my_token != self._load_token):
                return
            existing = self.lyrics_cache.get(trk.track_number)
            if not force_refresh and existing:
                return
            lines = lookup_track_lyrics(trk.title, trk.artist, trk.duration_sec, trk.builtin_lrc)
            if self._closed or (my_token and my_token != self._load_token):
                return
            if lines:
                self.lyrics_cache[trk.track_number] = lines
            else:
                # 若期间其他高优/预取线程已写入歌词，绝不用空结果覆盖缓存或当前显示歌词
                lines = self.lyrics_cache.get(trk.track_number) or []
            if (
                self.current_toc
                and 0 <= self.current_track_index < len(self.current_toc.tracks)
                and self.current_toc.tracks[self.current_track_index].track_number == trk.track_number
            ):
                if lines or not self.current_lyrics:
                    if self.current_lyrics != lines:
                        self.current_lyrics = lines
                        self._bump_lyrics()
        finally:
            if _fetch_key is not None:
                self._lyrics_fetching_keys.discard(_fetch_key)

    @staticmethod
    def _lyrics_quality_ok(lines) -> bool:
        """
        判断一份歌词是否「够好」：行数够 + 翻译覆盖率达标。
        逐字时间轴不参与判定——缺失时由前端按行时长合成，所以只需关注翻译是否残缺。
        不达标时后台会重新抓取，用于修复历史抓轨时用旧对齐逻辑存下的「有的句子有翻译、有的没有」。
        """
        if not lines or len(lines) < 4:
            return False
        n = len(lines)
        with_trans = sum(1 for ln in lines if isinstance(ln, dict) and ln.get("translation"))
        return with_trans >= n * 0.7

    def _prefetch_lyrics_async(self, my_token: int = 0):
        """
        并发预取整张专辑所有音轨的歌词：
        将当前播放音轨置于优先队列，并采用 as_completed 逐首即时落地更新，
        避免第一首歌等待整张专辑全部查询完毕后才显示歌词。
        """
        if self._closed:
            return
        toc_ref = self.current_toc
        if not toc_ref or not toc_ref.tracks:
            return

        cur_tn = None
        if 0 <= self.current_track_index < len(toc_ref.tracks):
            cur_tn = toc_ref.tracks[self.current_track_index].track_number

        pending = []
        for trk in toc_ref.tracks:
            if getattr(trk, "is_data_track", False):
                continue
            existing = self.lyrics_cache.get(trk.track_number)
            has_words = bool(existing and any(isinstance(ln, dict) and ln.get("words") for ln in existing))
            if trk.track_number in self.lyrics_locked_tracks:
                # 尊重手动锁定（含逐字或双语达标）；但旧版归档的无逐字、无翻译“伪锁定”轨道允许升级
                if existing and (has_words or self._lyrics_quality_ok(existing)):
                    continue
            if (my_token, trk.track_number, trk.title, trk.artist) in self._lyrics_fetching_keys:
                continue
            if existing and self._lyrics_quality_ok(existing) and has_words:
                continue
            pending.append(
                {
                    "track_number": trk.track_number,
                    "title": trk.title,
                    "artist": trk.artist,
                    "duration_sec": trk.duration_sec,
                    "builtin_lrc": getattr(trk, "builtin_lrc", "") or "",
                }
            )
        if not pending:
            return

        # 当前正在播放的音轨（通常为第 1 首）优先提交抓取
        if cur_tn is not None:
            pending.sort(key=lambda item: 0 if item["track_number"] == cur_tn else 1)

        improved = {}
        is_local = bool(getattr(toc_ref, "is_local", False))
        disc_id = getattr(toc_ref, "disc_id", "")

        def _lyr_rank(lns):
            if not lns:
                return (0, 0, 0)
            tr = sum(1 for ln in lns if isinstance(ln, dict) and ln.get("translation"))
            wd = sum(1 for ln in lns if isinstance(ln, dict) and ln.get("words"))
            return (tr, wd, len(lns))

        def _fetch_one(item: dict):
            try:
                tn = int(item["track_number"])
                dur = float(item["duration_sec"] or 0.0)
                lines = lookup_track_lyrics(
                    item["title"],
                    item["artist"],
                    dur,
                    item["builtin_lrc"],
                )
                if lines and not any(isinstance(ln, dict) and ln.get("words") for ln in lines):
                    lines = enrich_lyrics_with_word_timings(
                        item["title"], item["artist"], dur, lines
                    )
                return tn, lines
            except Exception:
                return int(item["track_number"]), []

        workers = max(1, min(2, len(pending)))
        with ThreadPoolExecutor(max_workers=workers) as pool:
            futures = [pool.submit(_fetch_one, item) for item in pending]
            for fut in as_completed(futures):
                if self._closed or (my_token and my_token != self._load_token):
                    return
                try:
                    tn, lines = fut.result()
                except Exception:
                    continue
                if not lines:
                    continue
                current = self.lyrics_cache.get(tn)
                if current is None or _lyr_rank(lines) > _lyr_rank(current) or not self._lyrics_quality_ok(current):
                    if current is not None and _lyr_rank(lines) < _lyr_rank(current):
                        continue
                    self.lyrics_cache[tn] = lines
                    improved[tn] = lines
                    if (
                        self.current_toc
                        and 0 <= self.current_track_index < len(self.current_toc.tracks)
                        and self.current_toc.tracks[self.current_track_index].track_number == tn
                    ):
                        if self.current_lyrics != lines:
                            self.current_lyrics = lines
                            self._bump_lyrics()

        # 本地唱片：把重新抓到的优质歌词回写 album.json，让修复长期生效
        if improved and is_local and disc_id:
            def _persist():
                for tn, lyr in improved.items():
                    try:
                        self.library_manager.update_track_lyrics(disc_id, tn, lyr)
                    except Exception:
                        pass

            threading.Thread(target=_persist, daemon=True).start()

    def _on_player_position(self, elapsed: float):
        self.elapsed_sec = elapsed

    def _on_player_finished(self):
        if self._closed:
            return
        if self.play_mode == "one":
            self._start_track(self.current_track_index)
        else:
            self.next_track()

    def _on_player_error(self, msg: str):
        if self._closed:
            return
        self.status_text = msg
        if (
            self.current_toc
            and not getattr(self.current_toc, "is_local", False)
            and not self.current_toc.is_simulated
            and not WindowsCdDriveManager.is_disc_ready(self.current_toc.drive_letter)
        ):
            self._handle_disc_removed(self.current_toc.drive_letter)


class DiscflowJsApi:
    """
    轻量纯方法 JS 桥接门面（所有内部属性均以 _ 开头）：
    防止 pywebview.util.get_functions 递归反射遍历 Window.native (WinForms COM 对象)
    或 CddaWaveOutPlayer 实例，彻底消除启动期的递归风暴与 COM 跨线程异常。
    """

    def __init__(self, controller: DiscflowController):
        self._ctrl = controller

    def poll_state(
        self,
        client_meta_ver: int = -1,
        client_lyrics_ver: int = -1,
        client_track_index: int = -1,
    ) -> dict:
        return self._ctrl.poll_state(client_meta_ver, client_lyrics_ver, client_track_index)

    def ui_ready(self):
        self._ctrl._apply_win11_rounded_corners()
        self._ctrl.ui_ready()

    def minimize_window(self):
        self._ctrl.minimize_window()

    def toggle_maximize_window(self) -> bool:
        return self._ctrl.toggle_maximize_window()

    def close_window(self):
        self._ctrl.close_window()

    def set_theme_mode(self, mode: str) -> bool:
        return self._ctrl.set_theme_mode(mode)

    def begin_window_resize(self, edge_code: int):
        self._ctrl.begin_window_resize(edge_code)

    def check_for_updates(self, force: bool = False) -> dict:
        return self._ctrl.check_for_updates(force)

