# Backwards compatibility alias
AppleMusicCdController = DiscflowController


def main():
    _enable_dpi_awareness()
    controller = DiscflowController()
    js_api = DiscflowJsApi(controller)
    win_w, win_h, win_x, win_y, win_max = DiscflowController._load_initial_window_bounds()
    controller._saved_maximized = win_max
    init_prefs = load_user_preferences()
    init_theme = "light" if init_prefs.get("themeMode") == "light" else "dark"
    init_state = controller.poll_state(-1, -1, -1)
    init_html = render_frontend_html(init_prefs=init_prefs, init_state=init_state)
    win = webview.create_window(
        title=APP_NAME,
        html=init_html,
        js_api=js_api,
        width=win_w,
        height=win_h,
        x=win_x,
        y=win_y,
        min_size=(880, 620),
        maximized=win_max,
        background_color="#F5F5F7" if init_theme == "light" else "#000000",
        frameless=True,
        easy_drag=False,
    )
    controller.bind_window(win)
    win.events.closing += controller.on_window_closing
    win.events.closed += controller.shutdown
    win.events.loaded += lambda: controller.ui_ready()
    webview.start(gui="edgechromium", debug=False)


if __name__ == "__main__":
    main()
